export const BLOCKED_COMMAND_PATTERNS = [
  /rm\s+-rf\s+\//,
  /rmdir\s+\/s\s+\/q\s+[a-zA-Z]:\\/i,
  /del\s+\/f\s+\/s\s+\/q\s+[a-zA-Z]:\\/i,
  /mkfs/,
  /dd\s+if=/,
  /format\s+[a-zA-Z]:/i,
  />\s*\/dev\/(sda|hda|nvme)/,
  />\s*\\\\.\\PhysicalDrive/,
];

let wakeWordProcess: ChildProcess | null = null;

function resolveWakeWordScriptPath() {
  const candidates = [
    path.join(process.cwd(), "wake_word_bg.py"),
    path.join(__dirname, "../wake_word_bg.py"),
    path.join(process.resourcesPath || "", "wake_word_bg.py"),
  ];

  for (const candidate of candidates) {
    if (candidate && fs.existsSync(candidate)) {
      return candidate;
    }
  }

  return path.join(__dirname, "../wake_word_bg.py");
}

function resolvePythonExecutable() {
  const explicitPath = process.env.Theta_PYTHON_PATH;
  if (explicitPath && fs.existsSync(explicitPath)) {
    return explicitPath;
  }

  if (process.platform === "win32") {
    const venvPython = path.join(process.cwd(), ".venv", "Scripts", "python.exe");
    if (fs.existsSync(venvPython)) {
      return venvPython;
    }
  }

  return "python";
}

export function startWakeWordDetector(mainWindow: BrowserWindow) {
  if (wakeWordProcess) return;

  const pythonExecutable = resolvePythonExecutable();
  const wakeWordScript = resolveWakeWordScriptPath();
  console.log(`Starting Wake Word Detector (Python): ${pythonExecutable}`);

  try {
    wakeWordProcess = spawn(pythonExecutable, [wakeWordScript]);

    wakeWordProcess.stdout?.on("data", (data) => {
      try {
        const output = data.toString().trim();
        const lines = output.split("\n");
        for (const line of lines) {
          if (!line.trim()) continue;
          const result = JSON.parse(line);
          mainWindow.webContents.send("wake-word-detected", result);
        }
      } catch (e) {
        console.error("Error parsing wake word output:", e);
      }
    });

    wakeWordProcess.stderr?.on("data", (data) => {
      console.error(`Wake Word Error: ${data}`);
    });

    wakeWordProcess.on("close", (code) => {
      console.log(`Wake word process exited with code ${code}`);
      wakeWordProcess = null;
    });
  } catch (error) {
    console.error("Failed to start wake word detector:", error);
  }
}

export function killWakeWordProcess() {
  if (wakeWordProcess) {
    wakeWordProcess.kill();
    wakeWordProcess = null;
  }
}

export async function getDetailedSystemInfo() {
  const [cpu, mem, graphics, os, network, battery, fsSize] = await Promise.all([
    si.cpu(),
    si.mem(),
    si.graphics(),
    si.osInfo(),
    si.networkInterfaces(),
    si.battery(),
    si.fsSize(),
  ]);
  return { cpu, mem, graphics, os, network, battery, fsSize };
}

export async function getProcesses() {
  const processes = await si.processes();
  const sorted = processes.list
    .sort((a, b) => b.cpu - a.cpu)
    .slice(0, 20)
    .map((p) => ({ name: p.name, pid: p.pid, cpu: p.cpu, mem: p.mem }));
  return sorted;
}

export function killProcess(pid: number) {
  process.kill(pid);
}

export function execCommand(command: string): Promise<{ success: boolean; stdout?: string; stderr?: string; error?: string }> {
  return new Promise((resolve) => {
    exec(command, { maxBuffer: 10 * 1024 * 1024 }, (error, stdout, stderr) => {
      resolve({ success: !error, stdout, stderr, error: error?.message });
    });
  });
}

import * as fs from "node:fs";
import * as http from "node:http";
import * as path from "node:path";

export function startProductionServer(distPath: string, initialPort: number = 45678): Promise<number> {
  return new Promise((resolve, reject) => {
    let currentPort = initialPort;

    const productionServer = http.createServer((req, res) => {
      const filePath = path.join(distPath, req.url === "/" ? "index.html" : (req.url || ""));

      // Security: prevent directory traversal
      if (!filePath.startsWith(distPath)) {
        res.writeHead(403);
        res.end("Forbidden");
        return;
      }

      const extname = path.extname(filePath).toLowerCase();
      const mimeTypes: Record<string, string> = {
        ".html": "text/html",
        ".js": "application/javascript",
        ".css": "text/css",
        ".json": "application/json",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".gif": "image/gif",
        ".svg": "image/svg+xml",
        ".wav": "audio/wav",
        ".mp3": "audio/mpeg",
        ".mp4": "video/mp4",
        ".woff": "font/woff",
        ".woff2": "font/woff2",
        ".ttf": "font/ttf",
        ".ico": "image/x-icon",
      };

      const contentType = mimeTypes[extname] || "application/octet-stream";

      fs.readFile(filePath, (error, content) => {
        if (error) {
          if (error.code === "ENOENT") {
            // SPA fallback - serve index.html for any unknown route
            fs.readFile(path.join(distPath, "index.html"), (err, indexContent) => {
              if (err) {
                res.writeHead(500);
                res.end("Server Error");
              } else {
                res.writeHead(200, { "Content-Type": "text/html" });
                res.end(indexContent, "utf-8");
              }
            });
          } else {
            res.writeHead(500);
            res.end(`Server Error: ${error.code}`);
          }
        } else {
          res.writeHead(200, { "Content-Type": contentType });
          res.end(content, "utf-8");
        }
      });
    });

    productionServer.listen(currentPort, "127.0.0.1", () => {
      console.log(`Production server running at http://localhost:${currentPort}`);
      resolve(currentPort);
    });

    productionServer.on("error", (err) => {
      if (err.code === "EADDRINUSE") {
        currentPort++;
        productionServer.listen(currentPort, "127.0.0.1");
      } else {
        reject(err);
      }
    });
  });
}

