      const start = getRelPos(startRef.current, "right");
      return `M ${start.x} ${start.y} C ${start.x + (centerPos.x - start.x) * 0.5} ${start.y}, ${centerPos.x - (centerPos.x - start.x) * 0.5} ${centerPos.y}, ${centerPos.x} ${centerPos.y}`;
    };

