import { X, Settings, Database, Key, Trash2, Save, CheckCircle2, AlertCircle } from 'lucide-react';
import React, { useState, useEffect } from 'react';

import { useAudio } from '../../hooks/useAudio';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose }) => {
  const [apiKey, setApiKey] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [appVersion, setAppVersion] = useState('');
  const [approvalAudit, setApprovalAudit] = useState<any[]>([]);
  const { playClick } = useAudio();

  useEffect(() => {
    if (isOpen) {
      (window as any).electronAPI.getGeminiToken().then((key: string) => {
        if (key) setApiKey(key);
      });
      // Fetch version
      (window as any).electronAPI.getAppVersion().then((version: string) => {
        setAppVersion(version);
      });

      if ((window as any).electronAPI.loadApprovalAuditLog) {
        (window as any).electronAPI.loadApprovalAuditLog().then((entries: any[]) => {
          setApprovalAudit(Array.isArray(entries) ? entries : []);
        });
      }
    }
  }, [isOpen]);

  const handleSaveKey = async () => {
    playClick();
    setIsSaving(true);
    setMessage(null);
    try {
      const success = await (window as any).electronAPI.saveGeminiToken(apiKey);
      if (success) {
        setMessage({ type: 'success', text: 'Settings updated successfully!' });
        setTimeout(() => setMessage(null), 3000);
      } else {
        throw new Error('Failed to save settings');
      }
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || 'Error saving settings' });
    } finally {
      setIsSaving(false);
    }
  };

  const handleClearMemory = async () => {
    playClick();
    if (
      window.confirm(
        'Bhai, kya aap waqai saari memories clear karna chahte hain? Yeh wapas nahi aayengi.'
      )
    ) {
      await (window as any).electronAPI.saveMemories([]);
      setMessage({ type: 'success', text: 'Memories cleared!' });
      setTimeout(() => setMessage(null), 3000);
    }
  };

  const handleClearApprovalAudit = async () => {
    playClick();
    await (window as any).electronAPI.clearApprovalAuditLog();
    setApprovalAudit([]);
    setMessage({ type: 'success', text: 'Approval audit log cleared.' });
    setTimeout(() => setMessage(null), 3000);
  };

  if (!isOpen) return null;

  const handleCloseInternal = () => {
    playClick();
    onClose();
  };

  return (
    <div className='fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm'>
      <div className='w-full max-w-2xl bg-j-panel border border-white/10 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]'>
        {/* Header */}
        <div className='p-6 border-b border-white/10 flex items-center justify-between bg-white/[0.02]'>
          <div className='flex items-center gap-3'>
            <div className='p-2 bg-j-cyan/10 rounded-lg'>
              <Settings size={20} className='text-j-cyan' />
            </div>
            <h2 className='text-xl font-bold text-white tracking-wide'>Main Settings</h2>
          </div>
          <button
            onClick={handleCloseInternal}
            className='p-2 hover:bg-white/5 rounded-full transition-colors'
          >
            <X size={20} className='text-j-text-secondary' />
          </button>
        </div>

        {/* Content */}
