  collapsed: Partial<Record<ModuleId, boolean>>;
  visibility: Record<ModuleId, boolean>;
  dailyTimes: {
    businessIdeas: string;
    linkedinPosts: string;
  };
  refreshIntervals: {
    worldIntelligenceHours: number;
  };
  businessIdeas: {
    date: string;
    ideas: BusinessIdea[];
  };
  worldIntelligence: {
    events: WorldEvent[];
    stories: NewsStory[];
