    playClick();
    const newNote: Note = {
      id: Date.now().toString(),
      title: 'Untitled Note',
      content: '',
      tags: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
      timestamp: Date.now(),
    };

    onSaveNote(newNote as any);
    setSelectedNoteId(newNote.id);
    setTitleInput(newNote.title);
    setTagsInput('');
    setEditorHtml('<p></p>');
    setIsDirty(false);
  };

  const handleSelectNote = (note: Note) => {
    playClick();
    setSelectedNoteId(note.id);
    setTitleInput(note.title || 'Untitled Note');
    setTagsInput((note.tags || []).join(', '));
    setEditorHtml(marked.parse(note.content || '') as string);
    setIsDirty(false);
  };

  const handleSave = () => {
    if (!selectedNote) return;

    const markdownBody = turndown.turndown(editorHtml || '<p></p>');
    const normalizedTags = tagsInput
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);

    const updatedNote: Note = {
      ...selectedNote,
      title: titleInput.trim() || 'Untitled Note',
      content: markdownBody,
      tags: normalizedTags,
      updatedAt: Date.now(),
      timestamp: Date.now(),
    };

    onSaveNote(updatedNote as any);
    setIsDirty(false);
  };

  const exportNote = (note: Note, format: 'md' | 'txt') => {
    const extension = format === 'md' ? 'md' : 'txt';
    const body = format === 'md' ? note.content : note.content.replace(/[#*_`>-]/g, '');
    const safeTitle = (note.title || 'note').replace(/[^a-z0-9-_ ]/gi, '').trim() || 'note';
    const fileName = `${safeTitle}.${extension}`;

    const blob = new Blob([body], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const filteredNotes = normalizedNotes.filter((note) => {
    const query = searchQuery.toLowerCase();
    return note.title.toLowerCase().includes(query) || note.content.toLowerCase().includes(query);
  });

  useEffect(() => {
    if (!editorContainerRef.current || quillRef.current) return;

    const quill = new Quill(editorContainerRef.current, {
      theme: 'snow',
      modules: {
        toolbar: {
          container: '#notes-rich-toolbar',
          handlers: {
            divider: function () {
              const range = quill.getSelection(true);
              const index = range?.index || quill.getLength();
              quill.clipboard.dangerouslyPasteHTML(index, '<hr />');
              quill.setSelection(index + 1, 0);
            },
          },
        },
      },
    });

    quill.on('text-change', () => {
      if (isProgrammaticUpdateRef.current) return;
      setEditorHtml(quill.root.innerHTML);
      setIsDirty(true);
    });

    quillRef.current = quill;

    return () => {
      quillRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!selectedNote || !quillRef.current) return;

    isProgrammaticUpdateRef.current = true;
    quillRef.current.clipboard.dangerouslyPasteHTML(
      marked.parse(selectedNote.content || '') as string
    );
    setTimeout(() => {
      isProgrammaticUpdateRef.current = false;
    }, 0);
  }, [selectedNote?.id]);

  useEffect(() => {
    if (normalizedNotes.length === 0) return;
    if (!selectedNoteId) {
      handleSelectNote(normalizedNotes[0]);
    }
  }, [normalizedNotes, selectedNoteId]);

  useEffect(() => {
    const hideContextMenu = () => setContextMenu(null);
    window.addEventListener('click', hideContextMenu);
    return () => window.removeEventListener('click', hideContextMenu);
  }, []);

  return (
    <div className='h-full w-full flex rounded-3xl overflow-hidden border border-white/10 bg-j-panel/60 backdrop-blur-xl'>
      <aside className='w-[320px] border-r border-white/10 p-4 flex flex-col gap-4 bg-black/20'>
        <div className='flex items-center justify-between'>
          <div>
            <h2 className='text-xl font-semibold text-white'>Notes</h2>
            <p className='text-[11px] text-j-text-muted'>Rich editor + markdown storage</p>
          </div>
          <button
            onClick={handleCreateNew}
            className='p-2 rounded-xl bg-j-cyan/15 text-j-cyan border border-j-cyan/30 hover:bg-j-cyan hover:text-black transition-colors'
          >
            <Plus size={16} />
          </button>
        </div>

        <div className='relative'>
          <Search size={14} className='absolute left-3 top-3 text-j-text-muted' />
          <input
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            placeholder='Search title or content...'
            className='w-full rounded-xl bg-white/5 border border-white/10 pl-9 pr-3 py-2 text-xs text-j-text-primary focus:outline-none focus:border-j-cyan/40'
          />
        </div>

        <div className='flex-1 overflow-y-auto custom-scrollbar space-y-2 pr-1'>
          {filteredNotes.map((note) => (
            <button
              key={note.id}
              onClick={() => handleSelectNote(note)}
              onContextMenu={(event) => {
                event.preventDefault();
                setContextMenu({ note, x: event.clientX, y: event.clientY });
              }}
              className={`rounded-2xl border p-3 cursor-pointer transition-colors ${
                selectedNoteId === note.id
                  ? 'border-j-cyan/40 bg-j-cyan/10'
                  : 'border-white/10 bg-white/5 hover:border-white/20'
              }`}
            >
              <div className='flex items-start justify-between gap-2'>
                <h3 className='text-sm text-white font-semibold truncate'>
                  {note.title || 'Untitled Note'}
                </h3>
                <button
                  onClick={(event) => {
                    event.stopPropagation();
                    playClick();
                    onDeleteNote(note.id);
                  }}
                  className='p-1 rounded-lg hover:bg-rose-500/20 text-j-text-muted hover:text-rose-400 transition-colors'
                >
                  <Trash2 size={12} />
                </button>
              </div>
              <p className='text-[11px] text-j-text-secondary line-clamp-2 mt-1'>
                {note.content || 'No content'}
              </p>
              <div className='text-[10px] text-j-text-muted mt-2'>
                {new Date(note.updatedAt || note.timestamp || Date.now()).toLocaleString()}
              </div>
            </button>
          ))}

          {filteredNotes.length === 0 && (
            <div className='text-xs text-j-text-muted border border-white/10 rounded-xl p-4'>
              No matching notes found.
            </div>
          )}
        </div>
      </aside>

      <section className='flex-1 p-5 flex flex-col gap-4'>
        {!selectedNote ? (
          <div className='h-full flex items-center justify-center text-j-text-muted text-sm'>
            Select a note to start editing.
          </div>
        ) : (
          <>
            <div className='flex items-center justify-between gap-3'>
              <div className='flex-1 grid grid-cols-1 md:grid-cols-2 gap-3'>
                <input
                  value={titleInput}
                  onChange={(event) => {
                    setTitleInput(event.target.value);
                    setIsDirty(true);
                  }}
                  placeholder='Note title'
                  className='w-full rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-sm text-j-text-primary focus:outline-none focus:border-j-cyan/40'
                />
                <input
                  value={tagsInput}
                  onChange={(event) => {
                    setTagsInput(event.target.value);
                    setIsDirty(true);
                  }}
                  placeholder='Tags (comma separated)'
                  className='w-full rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-sm text-j-text-primary focus:outline-none focus:border-j-cyan/40'
                />
              </div>

              <button
                onClick={handleSave}
                className='inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-j-cyan text-black font-semibold hover:brightness-110 transition-colors'
              >
                <Save size={14} />
                {isDirty ? 'Save' : 'Saved'}
              </button>
            </div>

            <div
              id='notes-rich-toolbar'
              className='rounded-xl border text-black border-white/10 bg-black p-2'
            >
              <span className='ql-formats'>
                <select className='ql-header' defaultValue=''>
                  <option value='1'>H1</option>
                  <option value='2'>H2</option>
                  <option value='3'>H3</option>
                  <option value=''>Normal</option>
                </select>
              </span>
              <span className='ql-formats'>
                <button className='ql-bold' />
                <button className='ql-italic' />
                <button className='ql-underline' />
                <button className='ql-strike' />
              </span>
              <span className='ql-formats'>
                <button className='ql-list' value='ordered' />
                <button className='ql-list' value='bullet' />
              </span>
              <span className='ql-formats'>
                <button className='ql-blockquote' />
                <button className='ql-code-block' />
                <button className='ql-divider'>HR</button>
              </span>
              <span className='ql-formats'>
                <button className='ql-clean' />
              </span>
            </div>

            <div className='flex-1 rounded-2xl border border-white/10 overflow-hidden bg-white'>
              <div ref={editorContainerRef} className='h-full text-black' />
            </div>

            <div className='text-[11px] text-j-text-muted'>
              Notes are stored as markdown internally and rendered as rich text in editor.
            </div>
          </>
        )}
      </section>

      {contextMenu && (
        <div
          className='fixed z-[140] rounded-xl border border-white/10 bg-j-panel shadow-2xl p-1'
          style={{ left: contextMenu.x, top: contextMenu.y }}
        >
          <button
            onClick={() => exportNote(contextMenu.note, 'md')}
            className='w-full text-left px-3 py-2 text-xs text-j-text-primary hover:bg-white/5 rounded-lg inline-flex items-center gap-2'
          >
            <Download size={12} />
            Export as .md
          </button>
          <button
            onClick={() => exportNote(contextMenu.note, 'txt')}
            className='w-full text-left px-3 py-2 text-xs text-j-text-primary hover:bg-white/5 rounded-lg inline-flex items-center gap-2'
          >
            <FileText size={12} />
            Export as .txt
          </button>
        </div>
      )}
    </div>
  );
};

export default NotesSection;

import { Camera, CameraOff } from 'lucide-react';

import TodayHeadlines from '../TodayHeadlines';
import SystemAdvisorPanel, { type AdvisorRecommendation } from './SystemAdvisorPanel';
import { useAudio } from '../../hooks/useAudio';

interface SidebarLeftProps {
  currentWidth: number;
  isResizing: boolean;
  isCameraOn: boolean;
  isCameraLoading: boolean;
  videoRef: React.RefObject<HTMLVideoElement | null>;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
  toggleCamera: () => void;
  onStartResizing: () => void;
  dashboardData: any;
  isDashboardLoading: boolean;
  setIsUserModalOpen: (open: boolean) => void;
  setIsDashboardModalOpen: (open: boolean) => void;
  refreshDashboard: () => void;
  advisorRecommendations: AdvisorRecommendation[];
  isAdvisorScanning: boolean;
  onAdvisorScanNow: () => void;
  onAdvisorRunFix: (recommendation: AdvisorRecommendation) => void;
}

const SidebarLeft: React.FC<SidebarLeftProps> = ({
  currentWidth,
  isResizing,
  isCameraOn,
  isCameraLoading,
  videoRef,
  canvasRef,
  toggleCamera,
  onStartResizing,
  dashboardData,
  isDashboardLoading,
  setIsUserModalOpen,
  setIsDashboardModalOpen,
  refreshDashboard,
  advisorRecommendations,
  isAdvisorScanning,
  onAdvisorScanNow,
  onAdvisorRunFix,
}) => {
  const { playClick } = useAudio();
  return (
    <>
      <aside
        style={{
          width: currentWidth,
          paddingLeft: currentWidth > 0 ? undefined : 0,
          paddingRight: currentWidth > 0 ? undefined : 0,
          opacity: currentWidth > 0 ? 1 : 0,
        }}
        className={`flex border-r border-white/[0.03] flex-col p-2 md:p-4 lg:p-6 gap-4 lg:gap-6 shrink-0 bg-j-panel/90 backdrop-blur-3xl ${isResizing ? '' : 'sidebar-transition'} overflow-hidden relative shadow-2xl`}
      >
        {/* 1. Camera Panel */}
        <div className='h-[260px] md:h-[320px] w-full rounded-3xl border border-white/[0.1] bg-j-surface/40 flex flex-col items-center justify-center relative overflow-hidden group shadow-lg'>
          <div className='absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(0,229,255,0.05),transparent_75%)]' />

          {isCameraOn ? (
            <>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                className='absolute inset-0 w-full h-full object-cover rounded-3xl'
                style={{ opacity: isCameraLoading ? 0 : 1 }}
              />
              {isCameraLoading && (
                <div className='absolute inset-0 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm z-10 transition-opacity'>
                  <div className='w-8 h-8 border-2 border-j-cyan border-t-transparent rounded-full animate-spin mb-2' />
                  <span className='text-[10px] text-j-cyan font-mono uppercase tracking-widest'>
                    Waking Up...
                  </span>
                </div>
              )}
              <div className='absolute inset-0 pointer-events-none border-2 border-j-cyan/20 rounded-3xl animate-pulse' />
            </>
          ) : (
            <div className='flex flex-col items-center'>
              <CameraOff
                size={56}
                className='text-j-text-muted mb-4 opacity-40 group-hover:opacity-80 transition-opacity'
              />
              <span className='text-j-text-muted text-base tracking-wider font-light'>
                camera offline
              </span>
            </div>
          )}

          <button
            onClick={() => {
              playClick();
              toggleCamera();
            }}
            disabled={isCameraLoading}
            className={`absolute bottom-4 right-4 p-3 rounded-full border backdrop-blur-md transition-all z-20 ${
              isCameraOn
                ? 'bg-j-cyan/10 border-j-cyan/50 text-j-cyan shadow-[0_0_15px_rgba(0,229,255,0.2)]'
                : isCameraLoading
                  ? 'bg-j-amber/10 border-j-amber/50 text-j-amber animate-pulse'
                  : 'bg-white/5 border-white/10 text-j-text-muted hover:text-white'
            } ${isCameraLoading ? 'cursor-wait' : 'cursor-pointer hover:scale-105 active:scale-95'}`}
          >
            {isCameraOn ? <Camera size={20} /> : <CameraOff size={20} />}
          </button>

          <canvas ref={canvasRef} width={320} height={240} className='hidden' />
        </div>

        {/* 2. Bottom Panel (News Feed) */}
        <TodayHeadlines
          data={dashboardData}
          loading={isDashboardLoading}
          onMapClick={() => {
            playClick();
            setIsUserModalOpen(true);
          }}
          onSettingsClick={() => {
            playClick();
            setIsDashboardModalOpen(true);
          }}
          onRefresh={() => {
            playClick();
            refreshDashboard();
          }}
        />

        <SystemAdvisorPanel
          recommendations={advisorRecommendations}
          isScanning={isAdvisorScanning}
          onScanNow={() => {
            playClick();
            onAdvisorScanNow();
          }}
          onRunFix={onAdvisorRunFix}
        />
      </aside>

      {/* Resize Handle */}
      {currentWidth > 0 && (
        <button
          onMouseDown={onStartResizing}
          className='hidden lg:flex w-2 bg-transparent cursor-col-resize z-40 transition-all absolute top-16 bottom-0 items-center justify-center group'
          style={{ left: currentWidth - 4 }}
        >
          <div className='w-[1px] h-32 bg-white/5 group-hover:bg-j-cyan/30 transition-all rounded-full scale-y-0 group-hover:scale-y-100 origin-center duration-500' />
        </button>
      )}
    </>
  );
};

export default SidebarLeft;

import { MessageSquare, Paperclip, X, Plus } from 'lucide-react';
import React from 'react';

import { useAudio } from '../../hooks/useAudio';
import { ConnectionStatus } from '../../types';
import LogTerminal from '../LogTerminal';

interface SidebarRightProps {
  currentWidth: number;
  isResizing: boolean;
  rightPanelMode: 'chat' | 'terminal';
  setRightPanelMode: (mode: 'chat' | 'terminal') => void;
  messages: any[];
  logs: any[];
  status: ConnectionStatus;
  attachedFiles: any[];
  chatInput: string;
  setChatInput: (val: string) => void;
  handleSendChat: () => void;
  handleNativeFileSelect: () => void;
  removeFile: (idx: number) => void;
  messagesEndRef: React.RefObject<HTMLDivElement | null>;
  onStartResizing: () => void;
  isThinking?: boolean;
  currentThought?: string;
  thinkingEnabled?: boolean;
  setThinkingEnabled?: (enabled: boolean) => void;
  currentOutput?: string;
}

const SidebarRight: React.FC<SidebarRightProps> = ({
  currentWidth,
  isResizing,
  rightPanelMode,
  setRightPanelMode,
  messages,
  logs,
  status,
  attachedFiles,
  chatInput,
  setChatInput,
  handleSendChat,
  handleNativeFileSelect,
  removeFile,
  messagesEndRef,
  onStartResizing,
  isThinking,
  currentThought,
  thinkingEnabled,
  setThinkingEnabled,
  currentOutput,
}) => {
  const { playClick } = useAudio();
  return (
    <>
      {/* Resize Handle */}
      {currentWidth > 0 && (
        <div
          onMouseDown={onStartResizing}
          className='hidden xl:flex w-2 bg-transparent cursor-col-resize z-40 transition-all absolute top-16 bottom-0 items-center justify-center group'
          style={{ right: currentWidth - 4 }}
        >
          <div className='w-[1px] h-32 bg-white/5 group-hover:bg-j-cyan/30 transition-all rounded-full scale-y-0 group-hover:scale-y-100 origin-center duration-500' />
        </div>
      )}

      <aside
        style={{
          width: currentWidth,
          paddingLeft: currentWidth > 0 ? undefined : 0,
          paddingRight: currentWidth > 0 ? undefined : 0,
          opacity: currentWidth > 0 ? 1 : 0,
        }}
        className={`flex border-l border-white/10 p-2 md:p-4 xl:p-6 flex-col bg-j-panel/95 backdrop-blur-3xl ${isResizing ? '' : 'sidebar-transition'} overflow-hidden relative shadow-2xl sci-fi-grid`}
      >
        {/* Decorative Elements */}
        <div className='absolute top-0 right-0 w-32 h-32 bg-j-cyan/5 blur-3xl rounded-full -mr-16 -mt-16 pointer-events-none' />

        <div className='flex items-center justify-between mb-8 shrink-0 relative z-10'>
          <div>
            <h2 className='text-xs font-mono font-bold text-j-cyan tracking-[0.3em] uppercase'>
              {rightPanelMode === 'chat' ? 'System_Transcription' : 'Kernel_Logs'}
            </h2>
            <div className='h-0.5 w-8 bg-j-cyan mt-1 rounded-full shadow-[0_0_8px_rgba(0,229,255,0.5)]' />
          </div>

          <div className='flex bg-black/40 p-1 rounded-xl border border-white/10 shadow-inner'>
            <button
              onClick={() => {
                playClick();
                setRightPanelMode('chat');
              }}
              className={`px-4 py-2 rounded-lg text-xs font-mono uppercase tracking-widest transition-all flex items-center gap-2 ${
                rightPanelMode === 'chat'
                  ? 'bg-j-cyan/20 text-j-cyan ring-1 ring-j-cyan/30 shadow-[0_0_15px_rgba(0,229,255,0.1)]'
                  : 'text-j-text-muted hover:text-white'
              }`}
            >
              <span
                className={`w-1 h-1 rounded-full ${rightPanelMode === 'chat' ? 'bg-j-cyan animate-pulse' : 'bg-transparent'}`}
               />
              Chat
            </button>
            <button
              onClick={() => {
                playClick();
                setRightPanelMode('terminal');
              }}
              className={`px-4 py-2 rounded-lg text-xs font-mono uppercase tracking-widest transition-all flex items-center gap-2 ${
                rightPanelMode === 'terminal'
                  ? 'bg-j-cyan/20 text-j-cyan ring-1 ring-j-cyan/30 shadow-[0_0_15px_rgba(0,229,255,0.1)]'
                  : 'text-j-text-muted hover:text-white'
              }`}
            >
              <span
                className={`w-1 h-1 rounded-full ${rightPanelMode === 'terminal' ? 'bg-j-cyan animate-pulse' : 'bg-transparent'}`}
               />
              Logs
            </button>
          </div>
        </div>

        {/* Professional Deep Reasoning Toggle */}
        {rightPanelMode === 'chat' && (
          <div className='flex items-center justify-between px-4 mb-6 py-2 border-y border-white/5 bg-white/[0.02] backdrop-blur-sm'>
            <div className='flex items-center gap-3'>
              <div
                className={`w-1.5 h-1.5 rounded-full transition-all duration-500 ${thinkingEnabled ? 'bg-j-cyan shadow-[0_0_10px_cyan]' : 'bg-gray-500/50'}`}
               />
              <div className='flex flex-col'>
                <span
                  className={`text-[10px] font-mono font-bold tracking-widest uppercase transition-colors ${thinkingEnabled ? 'text-j-text-primary' : 'text-j-text-muted'}`}
                >
                  Deep Reasoning
                </span>
                <span className='text-[9px] text-white/30 hidden sm:block'>
                  {thinkingEnabled ? 'Logic & Strategy Active' : 'Fast Response Mode'}
                </span>
              </div>
            </div>

            <button
              onClick={() => {
                playClick();
                setThinkingEnabled?.(!thinkingEnabled);
              }}
              className={`relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full border border-white/10 transition-all duration-300 ease-in-out focus:outline-none ${thinkingEnabled ? 'bg-j-cyan/20 border-j-cyan/50' : 'bg-black/40'}`}
            >
              <span
                className={`pointer-events-none inline-block h-3 w-3 transform rounded-full shadow ring-0 transition duration-300 ease-in-out mt-0.5 ml-0.5 ${thinkingEnabled ? 'translate-x-4 bg-j-cyan shadow-[0_0_5px_white]' : 'translate-x-0 bg-gray-500'}`}
              />
            </button>
          </div>
        )}

        <div className='flex-1 flex flex-col min-h-0 relative z-10'>
          {rightPanelMode === 'chat' ? (
            <>
              {messages.length > 0 ? (
                <div className='flex-1 overflow-y-auto space-y-6 pr-2 no-scrollbar pb-4'>
                  {messages.map((msg, idx) => (
                    <div
                      key={msg.id || idx}
                      className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} group mb-4`}
                    >
                      <div
                        className='flex items-center gap-2 mb-1.5 px-1 w-full'
                        style={{
                          justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start',
                          flexDirection: msg.role === 'user' ? 'row' : 'row',
                        }}
                      >
                        {msg.role !== 'user' && (
                          <div className='flex items-center gap-2'>
                            <div className='w-1.5 h-1.5 rounded-full bg-j-cyan shadow-[0_0_5px_rgba(0,229,255,0.8)]' />
                            <span className='text-[9px] font-mono uppercase tracking-[0.2em] font-bold text-j-cyan'>
                              {msg.isStreaming ? 'Theta_TRANSCRIBING...' : 'Theta_RESPONSE'}
                            </span>
                          </div>
                        )}

                        {msg.role === 'user' && (
                          <div className='flex items-center gap-2'>
                            <span className='text-[9px] font-mono uppercase tracking-[0.2em] font-bold text-j-text-muted'>
                              USER_CMD
                            </span>
                            <div className='w-1.5 h-1.5 rounded-full bg-white/20' />
                          </div>
                        )}
                      </div>

                      {/* Persistent Thought Display */}
                      {msg.thought && (
                        <div className='w-full mb-2 animate-in fade-in duration-500'>
                          <div className='bg-j-surface/30 border-l border-j-cyan/20 pl-3 py-2 rounded-r-lg max-w-[90%]'>
                            <span className='text-[8px] font-mono text-j-cyan/50 tracking-widest uppercase block mb-1'>
                              Reasoning_Archive
                            </span>
                            <p className='text-[10px] text-j-text-secondary/60 italic leading-relaxed font-light'>
                              {msg.thought}
                            </p>
                          </div>
                        </div>
                      )}

                      <div
                        className={`p-4 rounded-2xl text-[12px] leading-[1.6] max-w-[95%] shadow-xl border transition-all duration-300 ${
                          msg.role === 'user'
                            ? 'bg-j-surface/90 border-white/10 text-j-text-primary rounded-tr-none group-hover:border-white/20'
                            : msg.isStreaming
                              ? 'bg-j-cyan/5 border-j-cyan/20 text-j-text-primary/90 rounded-tl-none italic shadow-[0_0_15px_rgba(0,229,255,0.05)]'
                              : 'bg-j-cyan/10 border-j-cyan/30 text-j-text-primary rounded-tl-none group-hover:border-j-cyan/50 shadow-[0_4px_25px_rgba(0,229,255,0.05)]'
                        }`}
                      >
                        {msg.text}
                        {msg.isStreaming && (
                          <span className='inline-block w-1.5 h-3 bg-j-cyan ml-1 animate-pulse align-middle' />
                        )}
                      </div>
                    </div>
                  ))}

                  {/* Live Thinking Block - Shows whenever thinking text exists */}
                  {currentThought && (
                    <div className='flex flex-col items-start px-2 animate-in fade-in slide-in-from-bottom-2 duration-300 mb-6'>
                      <div className='bg-j-panel/30 border-l border-j-cyan/30 pl-3 py-2 my-1 rounded-r-lg max-w-[90%]'>
                        <div className='flex items-center gap-2 mb-1'>
                          <span className='text-[9px] font-mono tracking-widest text-j-cyan/60 uppercase flex items-center gap-1.5'>
                            {isThinking ? (
                              <>
                                <span className='w-1.5 h-1.5 bg-j-cyan rounded-full animate-pulse' />
                                Thinking...
                              </>
                            ) : (
                              <>Reasoning Complete</>
                            )}
                          </span>
                        </div>
                        <p className='text-[11px] text-j-text-secondary/70 italic leading-relaxed font-light'>
                          {currentThought}
                        </p>
                      </div>
                    </div>
                  )}

                  <div ref={messagesEndRef} />
                </div>
              ) : (
                <div className='flex-1 flex flex-col items-center justify-center text-center px-6'>
                  <div className='relative mb-8'>
                    <div className='absolute inset-0 bg-j-cyan/20 blur-2xl rounded-full animate-pulse-slow' />
                    <div className='relative w-24 h-24 border border-j-cyan/30 rounded-full flex items-center justify-center'>
                      <div className='w-16 h-16 border border-j-cyan/10 border-dashed rounded-full animate-spin-slow' />
                      <div className='absolute inset-0 flex items-center justify-center'>
                        <div className='w-2 h-2 bg-j-cyan rounded-full shadow-[0_0_15px_rgba(0,229,255,1)]' />
                      </div>
                    </div>
                  </div>
                  <h3 className='text-j-text-primary font-mono text-sm tracking-[0.2em] uppercase mb-2 font-bold decoration-j-cyan/50 underline-offset-8'>
                    Awaiting Interaction
                  </h3>
                  <p className='text-j-text-secondary text-[11px] leading-relaxed max-w-[240px] font-medium'>
                    Voice transcription aur chat history yahan numayan hogi.
                  </p>

                  <div className='grid grid-cols-3 gap-2 mt-12 w-full opacity-40'>
                    {[...Array(6)].map((_, i) => (
                      <div
                        key={i}
                        className='h-1 bg-j-text-secondary/30 rounded-full overflow-hidden'
                      >
                        <div
                          className='h-full bg-j-cyan/80 w-1/3 animate-data-flow'
                          style={{ animationDelay: `${i * 0.2}s` }}
                         />
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </>
          ) : (
            <div className='flex-1 overflow-hidden flex flex-col border border-white/5 rounded-2xl bg-black/20'>
              <LogTerminal logs={logs} className='flex-1' />
            </div>
          )}
        </div>

        {/* AI Interaction Section */}
        <div
          className={`mt-auto pt-6 border-t border-white/10 relative z-10 ${status !== ConnectionStatus.CONNECTED ? 'opacity-80' : ''}`}
        >
          {attachedFiles.length > 0 && (
            <div className='flex flex-wrap gap-2 mb-4 animate-in slide-in-from-bottom-2 duration-300'>
              {attachedFiles.map((file, idx) => (
                <div
                  key={idx}
                  className='flex items-center gap-2 px-3 py-1.5 bg-j-cyan/10 border border-j-cyan/30 rounded-xl group/file relative shadow-lg overflow-hidden'
                >
                  <div className='absolute inset-0 bg-j-cyan/5 -translate-x-full group-hover/file:translate-x-0 transition-transform duration-500' />
                  <span className='text-[10px] text-j-cyan font-mono truncate max-w-[120px] relative z-10'>
                    {file.name}
                  </span>
                  <button
                    onClick={() => {
                      playClick();
                      removeFile(idx);
                    }}
                    className='p-1 hover:bg-j-crimson/20 rounded-md text-j-text-muted hover:text-j-crimson transition-colors relative z-10'
                  >
                    <X size={10} />
                  </button>
                </div>
              ))}
              {attachedFiles.length < 5 && (
                <button
                  onClick={() => {
                    playClick();
                    handleNativeFileSelect();
                  }}
                  className='flex items-center justify-center w-8 h-8 rounded-xl border border-dashed border-j-cyan/30 text-j-cyan/40 hover:border-j-cyan hover:text-j-cyan hover:bg-j-cyan/5 transition-all'
                >
                  <Plus size={14} />
                </button>
              )}
            </div>
          )}

          <div className='relative group'>
            {/* Premium Glow effect behind input */}
            <div className='absolute -inset-[1px] bg-gradient-to-r from-j-cyan/40 via-j-blue/20 to-j-cyan/40 rounded-[22px] blur-sm opacity-0 group-focus-within:opacity-100 transition-all duration-700 animate-pulse-slow' />

            <div className='relative flex items-center bg-black/80 rounded-[20px] border border-white/20 group-focus-within:border-j-cyan/50 shadow-2xl transition-all duration-300'>
              <button
                onClick={() => {
                  playClick();
                  handleNativeFileSelect();
                }}
                disabled={status !== ConnectionStatus.CONNECTED || attachedFiles.length >= 5}
                className='absolute left-4 p-2 text-j-text-muted hover:text-j-cyan disabled:opacity-30 transition-all z-10'
                title='Attach Files'
              >
                <Paperclip size={18} />
              </button>

              <input
                type='text'
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendChat()}
                placeholder={
                  status === ConnectionStatus.CONNECTED ? 'TYPE_COMMAND_HERE...' : 'SYSTEM_OFFLINE'
                }
                disabled={status !== ConnectionStatus.CONNECTED}
                className={`w-full bg-transparent px-5 py-4 pl-14 pr-14 text-[13px] transition-all font-medium focus:outline-none 
                                    ${
                                      status === ConnectionStatus.CONNECTED
                                        ? 'text-j-text-primary placeholder:text-j-text-muted/60'
                                        : 'text-j-crimson/80 placeholder:text-j-crimson/60 font-black tracking-widest'
                                    }`}
              />

              <button
                onClick={() => {
                  playClick();
                  handleSendChat();
                }}
                disabled={
                  (!chatInput.trim() && attachedFiles.length === 0) ||
                  status !== ConnectionStatus.CONNECTED
                }
                className={`absolute right-2 p-2.5 rounded-2xl transition-all duration-300 shadow-lg ${
                  (chatInput.trim() || attachedFiles.length > 0) &&
                  status === ConnectionStatus.CONNECTED
                    ? 'bg-j-cyan text-black shadow-j-cyan/20 scale-100'
                    : 'bg-j-cyan/5 text-j-cyan/30 scale-95 opacity-50 shrink-0'
                }`}
              >
                <MessageSquare
                  size={18}
                  className={chatInput.trim() ? 'animate-in zoom-in duration-300' : ''}
                />
              </button>
            </div>
          </div>

          <div className='mt-4 flex items-center justify-between px-1'>
            <div className='flex items-center gap-2'>
              <span className='text-[8px] font-mono text-j-text-muted uppercase tracking-[0.2em]'>
                Theta-v2.5_core
              </span>
              {status === ConnectionStatus.CONNECTED && (
                <span className='text-[8px] px-1.5 py-0.5 rounded bg-j-cyan/10 text-j-cyan border border-j-cyan/20 animate-pulse'>
                  ACTIVE
                </span>
              )}
            </div>
            <div className='flex gap-1.5'>
              <div
                className={`w-1 h-3 rounded-full transition-all duration-500 ${status === ConnectionStatus.CONNECTED ? 'bg-j-cyan shadow-[0_0_5px_cyan]' : 'bg-white/5'}`}
               />
              <div
                className={`w-1 h-3 rounded-full transition-all duration-500 delay-75 ${status === ConnectionStatus.CONNECTED ? 'bg-j-cyan shadow-[0_0_5px_cyan]' : 'bg-white/5'}`}
               />
              <div
                className={`w-1 h-3 rounded-full transition-all duration-500 delay-150 ${status === ConnectionStatus.CONNECTED ? 'bg-j-cyan shadow-[0_0_5px_cyan]' : 'bg-white/5'}`}
               />
            </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default SidebarRight;

import { Paperclip, X, Brain, Database, User, Users } from 'lucide-react';

import { useAudio } from '../../hooks/useAudio';

interface SystemControlsProps {
  handleNativeFileSelect: () => void;
  attachedFiles: any[];
  removeFile: (idx: number) => void;
  setIsMemoryModalOpen: (open: boolean) => void;
  setIsHistoryModalOpen: (open: boolean) => void;
  setIsUserModalOpen: (open: boolean) => void;
  setIsContactsModalOpen: (open: boolean) => void;
  memoryInputRef: React.RefObject<HTMLInputElement | null>;
  addFilesRef: React.RefObject<HTMLDivElement | null>;
  memoryRef: React.RefObject<HTMLDivElement | null>;
  historyRef: React.RefObject<HTMLDivElement | null>;
  userRef: React.RefObject<HTMLDivElement | null>;
}

const SystemControls: React.FC<SystemControlsProps> = ({
  handleNativeFileSelect,
  attachedFiles,
  removeFile,
  setIsMemoryModalOpen,
  setIsHistoryModalOpen,
  setIsUserModalOpen,
  setIsContactsModalOpen,
  memoryInputRef,
  addFilesRef,
  memoryRef,
  historyRef,
  userRef,
}) => {
  const { playClick } = useAudio();
  return (
    <div className='flex flex-col gap-6'>
      {/* Add Files UI */}
      <div
        ref={addFilesRef}
        onClick={() => {
          playClick();
          handleNativeFileSelect();
        }}
        className='group px-4 py-3 rounded-2xl border border-j-cyan/20 bg-j-panel/40 flex items-center gap-4 transition-all hover:scale-[1.02] active:scale-[0.98] cursor-pointer relative overflow-hidden'
      >
        <div className='p-2 rounded-xl bg-j-cyan/10 text-j-cyan group-hover:scale-110 transition-transform'>
          <Paperclip size={18} className='group-hover:rotate-12 transition-transform' />
        </div>
        <div className='flex flex-col items-start'>
          <span className='text-xs font-bold text-white uppercase tracking-wider'>Add files</span>
          <span className='text-[9px] text-j-text-muted font-mono uppercase'>
            {attachedFiles.length > 0 ? `${attachedFiles.length} Selected` : 'Multimodal Input'}
          </span>
        </div>
        <div className='absolute inset-0 bg-j-cyan/5 opacity-0 group-hover:opacity-100 transition-opacity' />
      </div>

      {attachedFiles.length > 0 && (
        <div className='flex flex-wrap gap-2 max-w-[200px] mt-[-10px] ml-2 animate-in slide-in-from-top-2 duration-300'>
          {attachedFiles.map((file, idx) => (
            <div
              key={idx}
              className='flex items-center gap-2 px-2 py-1 bg-white/5 border border-white/10 rounded-lg group/file'
            >
              <span className='text-[8px] text-j-text-muted truncate max-w-[60px]'>
                {file.name}
              </span>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  playClick();
                  removeFile(idx);
                }}
                className='text-j-crimson opacity-50 hover:opacity-100'
              >
                <X size={10} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className='flex flex-col gap-4'>
        {[
          { label: 'memory', icon: Brain, color: 'j-crimson', ref: memoryRef },
          { label: 'history', icon: Database, color: 'j-blue', ref: historyRef },
          { label: 'contacts', icon: Users, color: 'j-cyan', ref: userRef },
          { label: 'User', icon: User, color: 'j-text-primary', ref: userRef },
        ].map((btn, idx) => (
          <div
            key={btn.label}
            ref={btn.ref}
            onClick={() => {
              playClick();
              if (btn.label === 'memory') {
                setIsMemoryModalOpen(true);
                setTimeout(() => memoryInputRef.current?.focus(), 200);
              } else if (btn.label === 'history') {
                setIsHistoryModalOpen(true);
              } else if (btn.label === 'contacts') {
                setIsContactsModalOpen(true);
              } else if (btn.label.toLowerCase() === 'user') {
                setIsUserModalOpen(true);
              }
            }}
            className={`
              group px-4 py-3 rounded-2xl border bg-j-panel/40 flex items-center gap-4 transition-all hover:scale-[1.02] active:scale-[0.98] cursor-pointer relative overflow-hidden
              ${btn.label === 'memory' ? 'border-j-crimson/20 hover:border-j-crimson/50' : 'border-white/[0.05] hover:border-white/20'}
            `}
          >
            <div
              className={`p-2 rounded-xl bg-${btn.color}/10 text-${btn.color} group-hover:scale-110 transition-transform`}
            >
              <btn.icon size={18} />
            </div>
            <div className='flex flex-col items-start'>
              <span className='text-xs font-bold text-white uppercase tracking-wider'>
                {btn.label}
              </span>
              <span className='text-[9px] text-j-text-muted font-mono uppercase'>
                System Access
              </span>
            </div>
            <div
              className={`absolute inset-0 bg-${btn.color}/5 opacity-0 group-hover:opacity-100 transition-opacity`}
             />
          </div>
        ))}
      </div>
    </div>
  );
};

export default SystemControls;

import { Plus, Trash2, CheckCircle2, Circle, AlertCircle, Clock, Tag } from 'lucide-react';
import React, { useState } from 'react';

import { useAudio } from '../../hooks/useAudio';

interface Task {
  id: string;
  text: string;
  completed: boolean;
  priority: 'low' | 'medium' | 'high' | 'critical';
  category: string;
  description?: string;
  dueAt?: string | null;
  reminder?: boolean;
  tags?: string[];
  timestamp: number;
}

interface TasksSectionProps {
  tasks: Task[];
  onSaveTasks: (tasks: Task[]) => void;
}

const TasksSection: React.FC<TasksSectionProps> = ({ tasks, onSaveTasks }) => {
  const [newTaskText, setNewTaskText] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');
  const [selectedPriority, setSelectedPriority] = useState<'low' | 'medium' | 'high' | 'critical'>(
    'medium'
  );
  const [selectedCategory, setSelectedCategory] = useState('Personal');
  const [dueAtInput, setDueAtInput] = useState('');
  const [reminderEnabled, setReminderEnabled] = useState(false);
  const [tagsInput, setTagsInput] = useState('');
  const [activeView, setActiveView] = useState<
    'all' | 'today' | 'upcoming' | 'completed' | 'priority'
  >('all');
  const [activeTag, setActiveTag] = useState<string>('all');

  const { playClick } = useAudio();

  const priorities = {
    low: { color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
    medium: { color: 'text-amber-400', bg: 'bg-amber-400/10' },
    high: { color: 'text-rose-400', bg: 'bg-rose-400/10' },
    critical: { color: 'text-red-400', bg: 'bg-red-500/20' },
  };

  const priorityWeight: Record<Task['priority'], number> = {
    low: 1,
    medium: 2,
    high: 3,
    critical: 4,
  };

  const normalizeTags = (rawTags: string) => {
    return rawTags
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
  };

  const isToday = (dateString?: string | null) => {
    if (!dateString) return false;
    const date = new Date(dateString);
    if (Number.isNaN(date.getTime())) return false;
    const now = new Date();
    return (
      date.getFullYear() === now.getFullYear() &&
      date.getMonth() === now.getMonth() &&
      date.getDate() === now.getDate()
    );
  };

  const isUpcoming = (dateString?: string | null) => {
    if (!dateString) return false;
    const date = new Date(dateString);
    if (Number.isNaN(date.getTime())) return false;
    const now = new Date();
    const endOfToday = new Date(now);
    endOfToday.setHours(23, 59, 59, 999);
    return date.getTime() > endOfToday.getTime();
  };

  const handleAddTask = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    playClick();
    if (!newTaskText.trim()) return;

    const newTask: Task = {
      id: Date.now().toString(),
      text: newTaskText.trim(),
      completed: false,
      priority: selectedPriority,
      category: selectedCategory,
      description: newTaskDescription.trim(),
      dueAt: dueAtInput ? new Date(dueAtInput).toISOString() : null,
      reminder: reminderEnabled,
      tags: normalizeTags(tagsInput),
      timestamp: Date.now(),
    };

    onSaveTasks([newTask, ...tasks]);
    setNewTaskText('');
    setNewTaskDescription('');
    setDueAtInput('');
    setReminderEnabled(false);
    setTagsInput('');
  };

  const toggleTask = (id: string) => {
    playClick();
    const updated = tasks.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t));
    onSaveTasks(updated);
  };

  const deleteTask = (id: string) => {
    playClick();
    const updated = tasks.filter((t) => t.id !== id);

    onSaveTasks(updated);
  };

  const categories = ['Work', 'Personal', 'Meeting', 'Finance', 'Operations', 'Sales'];

  const allTags = Array.from(
    new Set(tasks.flatMap((task) => (Array.isArray(task.tags) ? task.tags : [])))
  );

  const filteredTasks = tasks
    .filter((task) => {
      if (activeView === 'completed') return task.completed;
      if (activeView === 'today') return !task.completed && isToday(task.dueAt);
      if (activeView === 'upcoming') return !task.completed && isUpcoming(task.dueAt);
      if (activeView === 'priority') return !task.completed;
      return true;
    })
    .filter((task) => {
      if (activeTag === 'all') return true;
      return (task.tags || []).includes(activeTag);
    })
    .sort((a, b) => {
      if (activeView === 'priority') {
        return priorityWeight[b.priority] - priorityWeight[a.priority];
      }
      return b.timestamp - a.timestamp;
    });

  return (
    <div className='flex-1 flex flex-col h-full animate-appFadeIn'>
      <div className='flex justify-between items-center mb-8'>
        <div>
          <h2 className='text-2xl font-bold tracking-tight text-white mb-1'>Control Center</h2>
          <p className='text-j-text-muted text-xs uppercase tracking-widest'>
            Daily Operations & Goals
          </p>
        </div>
        <div className='flex gap-4'>
          <div className='px-4 py-2 bg-white/[0.03] border border-white/[0.05] rounded-xl flex items-center gap-3'>
            <div className='text-j-cyan flex items-center gap-2'>
              <CheckCircle2 size={16} />
              <span className='font-mono text-sm'>
                {tasks.filter((t) => t.completed).length}/{tasks.length}
              </span>
            </div>
            <div className='w-[1px] h-4 bg-white/10' />
            <span className='text-[10px] text-j-text-muted uppercase tracking-tighter'>
              Efficiency
            </span>
          </div>
        </div>
      </div>

      {/* Quick Add Bar */}
      <form onSubmit={handleAddTask} className='relative group mb-8 space-y-3'>
        <div className='absolute inset-0 bg-j-cyan/5 rounded-[32px] blur-xl opacity-0 group-focus-within:opacity-100 transition-opacity' />
        <div className='relative flex items-center bg-white/[0.03] border border-white/[0.1] rounded-[32px] p-2 pr-6 focus-within:border-j-cyan/40 transition-all'>
          <div className='flex-1 px-6'>
            <input
              type='text'
              value={newTaskText}
              onChange={(e) => setNewTaskText(e.target.value)}
              placeholder='Assign new objective...'
              className='w-full bg-transparent border-none focus:outline-none text-white text-lg placeholder:opacity-20'
            />
          </div>
          <div className='flex items-center gap-3'>
            <select
              value={selectedPriority}
              onChange={(e: any) => setSelectedPriority(e.target.value)}
              className='bg-white/5 border border-white/10 rounded-xl px-3 py-1.5 text-xs text-j-text-muted focus:outline-none hover:bg-white/10 cursor-pointer'
            >
              <option value='low'>Low Priority</option>
              <option value='medium'>Medium Priority</option>
              <option value='high'>High Priority</option>
              <option value='critical'>Critical Priority</option>
            </select>
            <button
              type='submit'
              className='bg-j-cyan text-j-void p-2.5 rounded-full hover:scale-110 active:scale-95 transition-all shadow-[0_0_20px_rgba(0,229,255,0.3)]'
            >
              <Plus size={20} strokeWidth={3} />
            </button>
          </div>
        </div>

        <div className='grid grid-cols-1 md:grid-cols-2 gap-3'>
          <textarea
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
            placeholder='Optional description'
            className='w-full min-h-[80px] bg-white/[0.03] border border-white/[0.08] rounded-2xl p-3 text-sm text-j-text-primary placeholder:text-j-text-muted focus:outline-none focus:border-j-cyan/40 transition-all'
          />

          <div className='space-y-3'>
            <div className='grid grid-cols-2 gap-2'>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className='bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs text-j-text-muted focus:outline-none'
              >
                {categories.map((cat) => (
                  <option key={cat} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>
              <input
                type='datetime-local'
                value={dueAtInput}
                onChange={(e) => setDueAtInput(e.target.value)}
                className='bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs text-j-text-muted focus:outline-none'
              />
            </div>

            <input
              type='text'
              value={tagsInput}
              onChange={(e) => setTagsInput(e.target.value)}
              placeholder='Tags (comma separated)'
              className='w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs text-j-text-muted focus:outline-none'
            />

            <label className='inline-flex items-center gap-2 text-xs text-j-text-secondary'>
              <input
                type='checkbox'
                checked={reminderEnabled}
                onChange={(e) => setReminderEnabled(e.target.checked)}
                className='accent-j-cyan'
              />
              Enable reminder alarm
            </label>
          </div>
        </div>
      </form>

      {/* Task Filters / Categories */}
      <div className='flex gap-2 mb-6 overflow-x-auto no-scrollbar pb-1'>
        {[
          { id: 'all', label: 'All' },
          { id: 'today', label: 'Today' },
          { id: 'upcoming', label: 'Upcoming' },
          { id: 'completed', label: 'Completed' },
          { id: 'priority', label: 'By Priority' },
        ].map((view) => (
          <button
            key={view.id}
            onClick={() => {
              playClick();
              setActiveView(view.id as any);
            }}
            className={`px-4 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all border ${
              activeView === view.id
                ? 'bg-j-cyan/10 border-j-cyan/30 text-j-cyan shadow-lg shadow-j-cyan/5'
                : 'bg-white/[0.03] border-white/5 text-j-text-muted hover:border-white/10'
            }`}
          >
            {view.label}
          </button>
        ))}
      </div>

      {allTags.length > 0 && (
        <div className='flex gap-2 mb-4 overflow-x-auto no-scrollbar'>
          <button
            onClick={() => setActiveTag('all')}
            className={`px-3 py-1 rounded-lg text-[11px] border ${activeTag === 'all' ? 'border-j-cyan/40 text-j-cyan bg-j-cyan/10' : 'border-white/10 text-j-text-muted'}`}
          >
            All Tags
          </button>
          {allTags.map((tag) => (
            <button
              key={tag}
              onClick={() => setActiveTag(tag)}
              className={`px-3 py-1 rounded-lg text-[11px] border ${activeTag === tag ? 'border-j-cyan/40 text-j-cyan bg-j-cyan/10' : 'border-white/10 text-j-text-muted'}`}
            >
              #{tag}
            </button>
          ))}
        </div>
      )}

      {/* Tasks List */}
      <div className='flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-3'>
        {filteredTasks.length > 0 ? (
          filteredTasks.map((task) => (
            <div
              key={task.id}
              className={`group flex items-center gap-4 p-4 rounded-2xl border transition-all ${
                task.completed
                  ? 'bg-white/[0.01] border-white/[0.02] opacity-50'
                  : 'bg-white/[0.03] border-white/[0.08] hover:border-white/[0.2] hover:bg-white/[0.05]'
              }`}
            >
              <button
                onClick={() => toggleTask(task.id)}
                className={`shrink-0 transition-colors ${task.completed ? 'text-j-cyan' : 'text-j-text-muted group-hover:text-white/40'}`}
              >
                {task.completed ? <CheckCircle2 size={24} /> : <Circle size={24} />}
              </button>

              <div className='flex-1 min-w-0'>
                <span
                  className={`block text-base leading-tight truncate ${task.completed ? 'line-through text-j-text-muted' : 'text-white/90'}`}
                >
                  {task.text}
                </span>
                {task.description && (
                  <p className='text-xs text-j-text-secondary mt-1 line-clamp-2'>
                    {task.description}
                  </p>
                )}
                <div className='flex items-center gap-4 mt-1'>
                  <span
                    className={`text-[10px] flex items-center gap-1 font-bold uppercase tracking-widest ${priorities[task.priority].color}`}
                  >
                    <AlertCircle size={10} />
                    {task.priority}
                  </span>
                  <span className='text-[10px] text-j-text-muted flex items-center gap-1'>
                    <Tag size={10} />
                    {task.category}
                  </span>
                  <span className='text-[10px] text-j-text-muted flex items-center gap-1'>
                    <Clock size={10} />
                    {new Date(task.timestamp).toLocaleTimeString([], {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </span>
                  {task.dueAt && (
                    <span className='text-[10px] text-j-text-muted flex items-center gap-1'>
                      <Clock size={10} />
                      Due {new Date(task.dueAt).toLocaleString()}
                    </span>
                  )}
                  {task.reminder && <span className='text-[10px] text-j-cyan'>Reminder On</span>}
                </div>
                {Array.isArray(task.tags) && task.tags.length > 0 && (
                  <div className='flex flex-wrap gap-1 mt-2'>
                    {task.tags.map((tag) => (
                      <span
                        key={`${task.id}-${tag}`}
                        className='text-[10px] px-2 py-0.5 rounded-full bg-white/10 text-j-text-secondary'
                      >
                        #{tag}
                      </span>
                    ))}
                  </div>
                )}
              </div>

              <button
                onClick={() => deleteTask(task.id)}
                className='p-2 opacity-0 group-hover:opacity-100 hover:bg-rose-500/20 text-rose-400 rounded-xl transition-all'
              >
                <Trash2 size={16} />
              </button>
            </div>
          ))
        ) : (
          <div className='py-20 flex flex-col items-center justify-center text-j-text-muted opacity-40'>
            <AlertCircle size={48} className='mb-4' />
            <p className='text-lg'>No objectives in queue. Ready for deployment.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default TasksSection;

import { Download, X, Check, RefreshCw } from 'lucide-react';
import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';

const electronAPI = (window as any).electronAPI;

interface UpdateInfo {
  version: string;
  releaseDate?: string;
}

interface DownloadProgress {
  percent: number;
  bytesPerSecond: number;
  transferred: number;
  total: number;
}

type UpdateState = 'idle' | 'available' | 'downloading' | 'ready';

const UpdateNotification: React.FC = () => {
  const [updateState, setUpdateState] = useState<UpdateState>('idle');
  const [updateInfo, setUpdateInfo] = useState<UpdateInfo | null>(null);
  const [downloadProgress, setDownloadProgress] = useState<DownloadProgress | null>(null);
  const [isExpanded, setIsExpanded] = useState(false);
  const [currentVersion, setCurrentVersion] = useState<string>('');

  // Helper to compare semver (Remote > Current)
  const isVersionNewer = (remote: string, current: string) => {
    if (!remote || !current) return false;
    // Strip 'v' prefix if present
    const r = remote.replace('v', '').split('.').map(Number);
    const c = current.replace('v', '').split('.').map(Number);

    for (let i = 0; i < Math.max(r.length, c.length); i++) {
      const rVal = r[i] || 0;
      const cVal = c[i] || 0;
      if (rVal > cVal) return true;
      if (rVal < cVal) return false;
    }
    return false;
  };

  useEffect(() => {
    console.log('UpdateNotification Component Mounted');

    // Get current app version
    electronAPI?.getAppVersion().then((version: string) => {
      console.log('Current App Version:', version);
      setCurrentVersion(version);
    });

    // Listen for debug logs from Main process
    if (electronAPI?.onUpdateLog) {
      electronAPI.onUpdateLog((message: string) => {
        console.log('%c[AutoUpdate Main Log]:', 'color: cyan', message);
      });
    }

    // Listen for update events (Natively handled by electron-updater, usually reliable)
    const unsubAvailable = electronAPI?.onUpdateAvailable((info: UpdateInfo) => {
      console.log('EVENT RECEIVED: Update available:', info);
      setUpdateInfo(info);
      setUpdateState('available');
      setIsExpanded(true);
    });

    const unsubProgress = electronAPI?.onUpdateDownloadProgress((progress: DownloadProgress) => {
      console.log('EVENT RECEIVED: Download progress:', progress);
      setDownloadProgress(progress);
    });

    const unsubDownloaded = electronAPI?.onUpdateDownloaded(() => {
      console.log('EVENT RECEIVED: Update downloaded');
      setUpdateState('ready');
      setDownloadProgress(null);
    });

    // MANUALLY CHECK FOR UPDATE ON MOUNT
    // Now using proper version comparison logic
    console.log('Invoking manual check-for-update from UI...');
    electronAPI
      ?.checkForUpdate()
      .then((res: any) => {
        console.log('Manual check result:', res);
        if (res && res.success && res.version) {
          electronAPI?.getAppVersion().then((currentVer: string) => {
            // FIX: Only show if Remote Version is GREATER than Current Version
            if (isVersionNewer(res.version, currentVer)) {
              console.log(`Update confirmed: ${res.version} is newer than ${currentVer}`);
              setUpdateInfo({ version: res.version });
              setUpdateState('available');
              setIsExpanded(true);
            } else {
              console.log(`No valid update: ${res.version} is not newer than ${currentVer}`);
            }
          });
        }
      })
      .catch((err: any) => console.error('Manual check error:', err));

    return () => {
      unsubAvailable?.();
      unsubProgress?.();
      unsubDownloaded?.();
    };
  }, []);

  const handleDownload = async () => {
    setUpdateState('downloading');
    await electronAPI?.downloadUpdate();
  };

  const handleInstall = async () => {
    await electronAPI?.installUpdate();
  };

  const handleDismiss = () => {
    setIsExpanded(false);
  };

  // Don't render anything if no update
  if (updateState === 'idle') return null;

  return (
    <>
      {/* Compact Badge - Always visible when update available */}
      {!isExpanded &&
        (updateState === 'available' ||
          updateState === 'downloading' ||
          updateState === 'ready') && (
          <button
            onClick={() => setIsExpanded(true)}
            className='flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium
                     bg-gradient-to-r from-emerald-500/20 to-cyan-500/20 
                     border border-emerald-500/30 text-emerald-400
                     hover:border-emerald-400/50 hover:shadow-[0_0_15px_rgba(16,185,129,0.3)]
                     transition-all duration-300 animate-pulse'
          >
            <Download size={12} />
            Update v{updateInfo?.version}
          </button>
        )}

      {/* Expanded Notification Panel - Portal to Document Body to ensure it's on top of everything */}
      {isExpanded &&
        createPortal(
          <div
            className='fixed top-20 right-6 z-[9999] w-80 
                        bg-j-surface/95 backdrop-blur-xl rounded-xl 
                        border border-white/10 shadow-2xl
                        animate-in slide-in-from-top-2 duration-300'
          >
            {/* Header */}
            <div className='flex items-center justify-between p-4 border-b border-white/5'>
              <div className='flex items-center gap-3'>
                <div
                  className='w-10 h-10 rounded-xl bg-gradient-to-br from-emerald-500/20 to-cyan-500/20 
                              flex items-center justify-center border border-emerald-500/30'
                >
                  {updateState === 'ready' ? (
                    <Check size={20} className='text-emerald-400' />
                  ) : updateState === 'downloading' ? (
                    <RefreshCw size={20} className='text-cyan-400 animate-spin' />
                  ) : (
                    <Download size={20} className='text-emerald-400' />
                  )}
                </div>
                <div>
                  <p className='text-sm font-semibold text-white'>
                    {updateState === 'ready'
                      ? 'Ready to Install'
                      : updateState === 'downloading'
                        ? 'Downloading...'
                        : 'Update Available'}
                  </p>
                  <p className='text-xs text-j-text-secondary'>
                    v{currentVersion} → v{updateInfo?.version}
                  </p>
                </div>
              </div>
              <button
                onClick={handleDismiss}
                className='p-1.5 rounded-lg hover:bg-white/5 text-j-text-secondary 
                         hover:text-white transition-colors'
              >
                <X size={16} />
              </button>
            </div>

            {/* Content */}
            <div className='p-4 space-y-4'>
              {/* Progress Bar - Show during download */}
              {updateState === 'downloading' && downloadProgress && (
                <div className='space-y-2'>
                  <div className='h-2 bg-j-void rounded-full overflow-hidden'>
                    <div
                      className='h-full bg-gradient-to-r from-emerald-500 to-cyan-500 
                               transition-all duration-300 rounded-full
                               shadow-[0_0_10px_rgba(16,185,129,0.5)]'
                      style={{ width: `${downloadProgress.percent}%` }}
                    />
                  </div>
                  <div className='flex justify-between text-xs text-j-text-secondary'>
                    <span>{downloadProgress.percent}%</span>
                    <span>
                      {(downloadProgress.transferred / 1024 / 1024).toFixed(1)} /
                      {(downloadProgress.total / 1024 / 1024).toFixed(1)} MB
                    </span>
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className='flex gap-2'>
                {updateState === 'available' && (
                  <>
                    <button
                      onClick={handleDismiss}
                      className='flex-1 px-4 py-2.5 rounded-lg text-sm font-medium
                               bg-white/5 hover:bg-white/10 text-j-text-secondary
                               hover:text-white transition-colors'
                    >
                      Later
                    </button>
                    <button
                      onClick={handleDownload}
                      className='flex-1 px-4 py-2.5 rounded-lg text-sm font-medium
                               bg-gradient-to-r from-emerald-500 to-cyan-500
                               hover:from-emerald-400 hover:to-cyan-400
                               text-white shadow-lg hover:shadow-emerald-500/25
                               transition-all duration-300'
                    >
                      Download Now
                    </button>
                  </>
                )}

                {updateState === 'ready' && (
                  <button
                    onClick={handleInstall}
                    className='w-full px-4 py-2.5 rounded-lg text-sm font-medium
                             bg-gradient-to-r from-emerald-500 to-cyan-500
                             hover:from-emerald-400 hover:to-cyan-400
                             text-white shadow-lg hover:shadow-emerald-500/25
                             transition-all duration-300 flex items-center justify-center gap-2'
                  >
                    <RefreshCw size={16} />
                    Install & Restart
                  </button>
                )}
              </div>

              {/* Info Text */}
              <p className='text-xs text-j-text-secondary text-center'>
                {updateState === 'ready'
                  ? 'Update downloaded. Click to install and restart.'
                  : updateState === 'downloading'
                    ? 'Please wait while the update downloads...'
                    : 'A new version of Theta AI is available.'}
              </p>
            </div>
          </div>,
          document.body
        )}
    </>
  );
};

export default UpdateNotification;

import { Maximize2, Minimize2, Zap, Layers, ZoomIn, ZoomOut, RotateCcw, Move, X } from 'lucide-react';
import React, { useRef, useEffect, useState } from 'react';

interface VisualHubProps {
    isExpanded: boolean;
    onToggleExpand: () => void;
    generatedImage: string | null;
    generatedDiagram: string | null;
    isVisualizing: boolean;
    isDiagramRendering: boolean;
    onReset: () => void;
    zoom: number;
    setZoom: React.Dispatch<React.SetStateAction<number>>;
    pan: { x: number; y: number };
    setPan: React.Dispatch<React.SetStateAction<{ x: number; y: number }>>;
    isDragging: boolean;
    setIsDragging: React.Dispatch<React.SetStateAction<boolean>>;
    dragStart: { x: number; y: number };
    setDragStart: React.Dispatch<React.SetStateAction<{ x: number; y: number }>>;
}

const VisualHub: React.FC<VisualHubProps> = ({
    isExpanded,
    onToggleExpand,
    generatedImage,
    generatedDiagram,
    isVisualizing,
    isDiagramRendering,
    onReset,
    zoom,
    setZoom,
    pan,
    setPan,
    isDragging,
    setIsDragging,
    dragStart,
    setDragStart
}) => {
    const diagramRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (generatedDiagram) {
            const renderDiagram = async () => {
                try {
                    if (diagramRef.current) diagramRef.current.innerHTML = '';
                    // @ts-ignore
                    const { svg } = await window.mermaid.render('mermaid-svg-' + Date.now(), generatedDiagram);
                    if (diagramRef.current) {
                        diagramRef.current.innerHTML = svg;
                    }
                } catch (err: any) {
                    console.error("Mermaid rendering failed:", err);
                    if (diagramRef.current) {
                        diagramRef.current.innerHTML = `<div class="p-6 border border-j-crimson/30 bg-j-crimson/5 rounded-xl text-j-crimson text-xs font-mono text-left overflow-auto max-h-full">
              <p class="font-bold mb-2 uppercase tracking-widest opacity-70">Rendering Error</p>
              <pre class="whitespace-pre-wrap">${err.message || 'Syntax Error'}</pre>
              <p class="mt-4 opacity-50 italic">AI will automatically attempt to repair the syntax.</p>
            </div>`;
                    }
                }
            };
            setTimeout(renderDiagram, 500);
        }
    }, [generatedDiagram]);

    const handleWheel = (e: React.WheelEvent) => {
        if (!generatedImage && !generatedDiagram) return;
        e.preventDefault();
        const scaleBy = 1.1;
        const newZoom = e.deltaY < 0 ? zoom * scaleBy : zoom / scaleBy;
        setZoom(Math.min(Math.max(0.1, newZoom), 5));
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        if ((generatedImage || generatedDiagram) && !isVisualizing && !isDiagramRendering) {
            setIsDragging(true);
            setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
        }
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (isDragging) {
            setPan({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
        }
    };

    const handleMouseUp = () => {
        setIsDragging(false);
    };

    const resetView = () => {
        setZoom(1);
        setPan({ x: 0, y: 0 });
    };

    return (
        <div className={`
      ${isExpanded
                ? 'fixed inset-4 z-[100] flex items-center justify-center'
                : 'hidden md:flex flex-[0.8] xl:flex-[1.0] items-start justify-center pb-6 lg:pb-12 px-4 lg:px-8'
            }
    `}>
            <div className={`
        ${isExpanded
                    ? 'w-full h-full rounded-[2.5rem] lg:rounded-[3.5rem]'
                    : 'w-full max-w-[650px] xl:max-w-[850px] h-full rounded-[2.5rem] lg:rounded-[3.5rem]'
                }
        border border-white/[0.08] bg-j-panel/95 backdrop-blur-3xl p-6 relative overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.8)] flex flex-col items-center justify-center text-center group transition-all duration-500 hover:border-j-cyan/20
      `}>
                {/* Sci-Fi Decorative Corners */}
                <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 border-j-cyan/30 rounded-tl-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />
                <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 border-j-cyan/30 rounded-tr-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 border-j-cyan/30 rounded-bl-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-j-cyan/30 rounded-br-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />

                {/* Background Grid Accent */}
                <div className="absolute inset-0 sci-fi-grid opacity-[0.2] pointer-events-none" />

                {/* Hub Status Indicator */}
                <div className="absolute top-6 left-6 flex items-center gap-2 px-3 py-1.5 bg-j-cyan/5 border border-j-cyan/10 rounded-lg pointer-events-none group-hover:bg-j-cyan/10 transition-all z-20">
                    <div className="w-1.5 h-1.5 bg-j-cyan rounded-full animate-ping" />
                    <span className="text-[9px] font-mono text-j-cyan font-bold tracking-[0.2em] uppercase">Visual Hub</span>
                    <div className="w-[1px] h-3 bg-j-cyan/20 mx-1" />
                    <span className="text-[8px] font-mono text-j-text-muted uppercase">Ready</span>
                </div>

                <div className="absolute top-6 right-6 flex gap-3 z-30">
                    <button
                        onClick={onToggleExpand}
                        className={`
              p-2.5 rounded-xl border transition-all duration-300 flex items-center justify-center
              ${isExpanded
                                ? 'bg-j-cyan/20 border-j-cyan/50 text-j-cyan shadow-[0_0_20px_rgba(0,229,255,0.2)]'
                                : 'bg-white/5 border-white/10 text-j-text-muted hover:text-j-cyan hover:border-j-cyan/30 hover:bg-j-cyan/5'
                            }
            `}
                        title={isExpanded ? "Minimize" : "Expand"}
                    >
                        {isExpanded ? <Minimize2 size={18} /> : <Maximize2 size={18} />}
                    </button>

                    {(generatedImage || generatedDiagram) && !isVisualizing && (
                        <button
                            onClick={onReset}
                            className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-[10px] font-mono text-j-text-muted hover:text-j-crimson hover:border-j-crimson/30 transition-all h-fit self-center font-bold uppercase tracking-widest"
                        >
                            Reset Hub
                        </button>
                    )}
                </div>

                <div
                    className={`
            flex-1 w-full h-full relative overflow-hidden flex items-center justify-center
            ${(generatedImage || generatedDiagram) && !isVisualizing && !isDiagramRendering ? 'cursor-grab active:cursor-grabbing' : ''}
          `}
                    onWheel={handleWheel}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    {/* Active Scanline Effect */}
                    {(generatedImage || generatedDiagram || isVisualizing || isDiagramRendering) && (
                        <div className="scanline" />
                    )}

                    {isVisualizing || isDiagramRendering ? (
                        <div className="flex flex-col items-center justify-center gap-6 animate-pulse">
                            <div className="relative">
                                <div className="w-24 h-24 border-b-2 border-j-cyan rounded-full animate-spin" />
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <Zap size={32} className="text-j-cyan animate-pulse" />
                                </div>
                            </div>
                            <div className="flex flex-col items-center gap-2">
                                <h3 className="text-sm font-mono text-j-cyan tracking-[0.4em] uppercase font-bold text-glow">
                                    {isDiagramRendering ? 'Designing' : 'Materializing'}
                                </h3>
                                <div className="flex gap-2">
                                    {[0, 1, 2].map(i => (
                                        <div key={i} className="w-1 h-3 bg-j-cyan/50 rounded-full animate-pulse" style={{ animationDelay: `${i * 0.2}s` }} />
                                    ))}
                                </div>
                            </div>
                            <p className="text-[9px] font-mono text-j-text-muted uppercase tracking-[0.2em] max-w-[300px] opacity-60">
                                {isDiagramRendering ? 'Constructing Visual Logic...' : 'Interpreting Neural Synapses into Visual Data...'}
                            </p>
                        </div>
                    ) : generatedImage ? (
                        <div
                            className="transition-transform duration-75 ease-out will-change-transform"
                            style={{
                                transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
                                transformOrigin: 'center center'
                            }}
                        >
                            <img
                                src={generatedImage}
                                alt="Generated AI"
                                className="max-w-[90vw] max-h-[80vh] object-contain rounded-[2rem] shadow-2xl pointer-events-none"
                            />
                        </div>
                    ) : generatedDiagram ? (
                        <div
                            className="w-full h-full flex items-center justify-center p-8 transition-transform duration-75 ease-out will-change-transform"
                            style={{
                                transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
                                transformOrigin: 'center center'
                            }}
                        >
                            <div ref={diagramRef} className="mermaid-viewer w-full pointer-events-none" />
                        </div>
                    ) : (
                        <div className="flex flex-col items-center">
                            <div className="w-16 h-16 rounded-full border border-dashed border-j-text-muted/30 flex items-center justify-center mb-6 group-hover:border-j-cyan/50 group-hover:rotate-45 transition-all duration-700">
                                <Layers className="text-j-text-muted group-hover:text-j-cyan" size={32} />
                            </div>
                            <h3 className="text-xl font-mono text-j-text-primary tracking-wider mb-4 leading-relaxed font-bold uppercase">
                                Visual Intelligence Hub
                            </h3>

                            <div className="space-y-2 text-j-text-secondary font-mono text-xs max-w-sm tracking-wide">
                                <p className="opacity-80">Images, Flowcharts, and Mindmaps will materialize here.</p>
                                <p className="text-j-cyan/60 font-medium">SYSTEM READY - AWAITING DATA INPUT</p>
                            </div>
                        </div>
                    )}
                </div>

                {/* Bottom Zoom/Pan Controls */}
                {(generatedImage || generatedDiagram) && !isVisualizing && !isDiagramRendering && (
                    <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-2 px-6 py-3 bg-black/60 backdrop-blur-xl border border-white/10 rounded-2xl z-30 animate-in slide-in-from-bottom-8 duration-700 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                        <button
                            onClick={() => setZoom(prev => Math.min(prev * 1.2, 5))}
                            className="p-2.5 bg-white/5 hover:bg-j-cyan/10 rounded-xl text-j-text-muted hover:text-j-cyan transition-all border border-transparent hover:border-j-cyan/30"
                            title="Zoom In"
                        >
                            <ZoomIn size={18} />
                        </button>
                        <div className="w-[1px] h-6 bg-white/10 mx-2" />
                        <div className="flex flex-col items-center">
                            <span className="text-[10px] font-mono text-j-cyan font-bold tracking-tighter">
                                {Math.round(zoom * 100)}%
                            </span>
                            <span className="text-[8px] font-mono text-j-text-muted uppercase tracking-widest opacity-50">Scale</span>
                        </div>
                        <div className="w-[1px] h-6 bg-white/10 mx-2" />
                        <button
