    const loadStartupData = async () => {
      try {
        const [
          loadedMemories, profile, loadedDashboardSettings, folders, vaultData,
          loadedHistory, loadedHistorySettings, loadedNotes, loadedTasks, loadedContacts
        ] = await Promise.all([
          electronAPI.loadMemories().catch(() => []),
          electronAPI.loadUserProfile().catch(() => ({})),
          electronAPI.loadDashboardSettings().catch(() => null),
          electronAPI.loadImportedFolders().catch(() => []),
          electronAPI.initializeVault().catch(() => null),
          electronAPI.loadHistory().catch(() => []),
          electronAPI.loadHistorySettings().catch(() => null),
          electronAPI.loadNotes().catch(() => []),
          electronAPI.loadTasks().catch(() => []),
          electronAPI.loadContacts().catch(() => [])
        ]);

        if (!isMounted) return;

        if (Array.isArray(loadedMemories)) setMemories(loadedMemories);
        if (profile && Object.keys(profile).length > 0) setUserProfile(profile);
        if (loadedDashboardSettings) setDashboardSettings(loadedDashboardSettings);
        if (Array.isArray(folders)) setImportedFolders(folders);
        if (vaultData?.vaultBase) setVaultPath(vaultData.vaultBase);
        if (Array.isArray(loadedHistory)) setHistory(loadedHistory);
        if (loadedHistorySettings) setHistorySettings(loadedHistorySettings);
        if (Array.isArray(loadedNotes)) setNotes(loadedNotes);
        if (Array.isArray(loadedTasks)) setTasks(loadedTasks);
        if (Array.isArray(loadedContacts)) setContacts(loadedContacts);
      } catch (error) {
        console.error("Error loading data:", error);
      }
    };

    const verifyApiKey = async () => {
      try {
        const key = await electronAPI.getGeminiToken();
        if (isMounted) setHasCheckedKey(true); // Always set true to finish load
      } catch {
        if (isMounted) setHasCheckedKey(true);
      }
    };

    loadStartupData();
    verifyApiKey();

    const fallback = window.setTimeout(() => { if (isMounted) setHasCheckedKey(true); }, 2000);
    return () => { isMounted = false; window.clearTimeout(fallback); };
  }, []);

  const handleUpdateProfile = async (field: string, value: string) => {
    const updated = { ...userProfile, [field]: value };
    setUserProfile(updated);
    await electronAPI.saveUserProfile(updated);
  };

  const handleUpdateDashboardSettings = async (settings: any) => {
    setDashboardSettings(settings);
    await electronAPI.saveDashboardSettings(settings);
  };

  const handleAddMemory = async (input: string) => {
    if (!input.trim()) return;
    const newMemo = { id: Date.now().toString(), content: input.trim(), category: "personal", timestamp: Date.now() };
    const updated = [newMemo, ...memories];
    setMemories(updated);
    await electronAPI.saveMemories(updated);
  };

  const handleDeleteMemory = async (id: string) => {
    const updated = memories.filter((m) => m.id !== id);
    setMemories(updated);
    await electronAPI.saveMemories(updated);
  };

  const handleMemoriesUpdated = async (updatedMemories: any[]) => {
    setMemories(updatedMemories);
    await electronAPI.saveMemories(updatedMemories);
  };

  const handleUpdateHistorySettings = async (settings: any) => {
    setHistorySettings(settings);
    await electronAPI.saveHistorySettings(settings);
  };

  const handleClearHistory = async () => {
    if (window.confirm("Are you sure you want to clear all conversation history?")) {
      setHistory([]);
      await electronAPI.clearHistory();
    }
  };

  const handleImportFolder = async () => {
    const result = await electronAPI.pickFolder();
    if (result) {
      const newFolders = [...importedFolders, result];
      setImportedFolders(newFolders);
      electronAPI.saveImportedFolders(newFolders);
    }
  };

  const handleRemoveFolder = (idx: number) => {
    const newFolders = importedFolders.filter((_, i) => i !== idx);
    setImportedFolders(newFolders);
    electronAPI.saveImportedFolders(newFolders);
  };

  const handleOpenFolder = async (folderPath: string) => {
    await electronAPI.openSystemItem({ target: folderPath });
  };

  const handleOpenVaultFolder = async (folderName: string) => {
    await electronAPI.openVaultFolder(folderName);
  };

  const handleSaveNote = async (note: any) => {
    const updated = notes.find((n) => n.id === note.id) ? notes.map((n) => (n.id === note.id ? note : n)) : [note, ...notes];
    setNotes(updated);
    await electronAPI.saveNotes(updated);
  };

  const handleDeleteNote = async (id: string) => {
    const updated = notes.filter((n) => n.id !== id);
    setNotes(updated);
    await electronAPI.saveNotes(updated);
  };

  const handleSaveTasks = async (updatedTasks: any[]) => {
    setTasks(updatedTasks);
    await electronAPI.saveTasks(updatedTasks);
    if (electronAPI?.syncTaskReminders) {
      await electronAPI.syncTaskReminders({ tasks: updatedTasks });
    }
  };

  const handleAddContact = async (name: string, phone: string) => {
    const trimmedName = name.trim();
    const trimmedPhone = phone.trim();
    if (!trimmedName || !trimmedPhone) return;
    const existing = contacts.find((c) => c.name.toLowerCase() === trimmedName.toLowerCase());
    const updatedContacts = existing
      ? contacts.map((c) => c.id === existing.id ? { ...c, phone: trimmedPhone, timestamp: Date.now() } : c)
      : [{ id: Date.now().toString(), name: trimmedName, phone: trimmedPhone, timestamp: Date.now() }, ...contacts];
    setContacts(updatedContacts);
    await electronAPI.saveContacts(updatedContacts);
  };

  const handleDeleteContact = async (id: string) => {
    const updatedContacts = contacts.filter((c) => c.id !== id);
    setContacts(updatedContacts);
    await electronAPI.saveContacts(updatedContacts);
  };

  const value = {
    memories, setMemories, handleAddMemory, handleDeleteMemory, handleMemoriesUpdated,
    userProfile, setUserProfile, handleUpdateProfile,
    dashboardSettings, setDashboardSettings, handleUpdateDashboardSettings,
    history, setHistory, historySettings, setHistorySettings, handleUpdateHistorySettings, handleClearHistory,
    importedFolders, setImportedFolders, handleImportFolder, handleRemoveFolder, handleOpenFolder, handleOpenVaultFolder,
    vaultPath, setVaultPath,
    notes, setNotes, handleSaveNote, handleDeleteNote,
    tasks, setTasks, handleSaveTasks,
    contacts, setContacts, handleAddContact, handleDeleteContact,
    hasCheckedKey, setHasCheckedKey
  };

  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error("useData must be used within a DataProvider");
  }
  return context;
};

import { useCallback } from 'react';

export const useAudio = () => {
  const playSound = useCallback((path: string, volume: number = 0.5) => {
    try {
      const audio = new Audio(path);
      audio.volume = volume;
      audio.play().catch(err => {
        // Silent fail if audio cannot play (e.g. user hasn't interacted yet)
        console.warn('Audio play failed:', err);
      });
    } catch (err) {
      console.error('Audio error:', err);
    }
  }, []);

  const playClick = useCallback(() => {
    playSound('audio/button.wav', 0.4);
  }, [playSound]);


  return { playSound, playClick };
};

import { GoogleGenAI, Modality, type LiveServerMessage, StartSensitivity, EndSensitivity } from '@google/genai';
import { useState, useRef, useCallback, useEffect } from 'react';

import { tools, getSystemInstruction } from '../config/gemini-config';
import { decode, decodeAudioData, createBlob } from '../lib/audio-helpers';
import { handleToolCalls } from '../lib/gemini-tool-runner';
import { type Message, ConnectionStatus } from '../types';
import { type SystemLog, type UseGeminiLiveProps } from '../types/gemini-live';

// Safely access electronAPI from window
const electronAPI = (window as any).electronAPI;

export const useGeminiLive = ({
  onSpeakingChanged,
  onImageGenerated,
  onMemoriesUpdated,
  onContactsUpdated,
  userProfile,
  onDiagramGenerated,
  onVisualizingChanged,
  vaultInfo,
  initialHistory = [],
  historySettings,
  onDashboardUpdated,
  onNotesUpdated,
  onTasksUpdated,
  onYouTubePlay,
  attachedFiles = []
}: UseGeminiLiveProps = {}) => {

  const maxContextMessages = Math.max(1, Number(historySettings?.maxContextMessages ?? 20));

  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [messages, setMessages] = useState<Message[]>(initialHistory.slice(-maxContextMessages));
  const [currentInput, setCurrentInput] = useState('');
  const [currentOutput, setCurrentOutput] = useState('');
  const [currentThought, setCurrentThought] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const thinkingEnabledRef = useRef(true);
  const [thinkingEnabled, setThinkingEnabledState] = useState(true);
  const currentTurnHasThinkingRef = useRef(false); // Track if current turn has received thinking
  const [logs, setLogs] = useState<SystemLog[]>([]);
  
  // Use ref to always get latest attachedFiles value (avoid closure issues)
  const attachedFilesRef = useRef(attachedFiles);
  
  // Update ref whenever attachedFiles prop changes
  useEffect(() => {
    attachedFilesRef.current = attachedFiles;
  }, [attachedFiles]);

  const setThinkingEnabled = useCallback((enabled: boolean) => {
    setThinkingEnabledState(enabled);
    thinkingEnabledRef.current = enabled;
  }, []);

  useEffect(() => {
    setMessages((prev) =>
      prev.length > maxContextMessages ? prev.slice(-maxContextMessages) : prev
    );
  }, [maxContextMessages]);

