              : appended;
          });
          addLog('info', `User sent message: ${text.substring(0, 30)}${text.length > 30 ? '...' : ''}`);
        } else {
          addLog('info', `Sent background system command`);
        }
      } catch (err) {


        console.error('Error sending text message:', err);
      }
    }
  }, [status, addLog, maxContextMessages, setThinkingEnabled]);

  const sendMultimodalMessage = useCallback((text: string, attachments: { name: string, data: string, mimeType: string }[]) => {
    if (sessionRef.current && status === ConnectionStatus.CONNECTED) {
      try {
        // Keep local context bounded before each outbound turn.
        setMessages((prev) => (prev.length > maxContextMessages ? prev.slice(-maxContextMessages) : prev));

        const fileNames = attachments.map(f => f.name).join(', ');
        addLog('info', `Sending ${attachments.length} files to Theta: ${fileNames}`);

        // Build parts array: FILES FIRST, then TEXT PROMPT
        // This ensures AI sees the file data before the question (proper context)
        const parts: any[] = [];

        // Add all file attachments as inlineData parts
        attachments.forEach(file => {
          const rawData = file.data.includes(',') ? file.data.split(',')[1] : file.data;
          parts.push({
            inlineData: {
              mimeType: file.mimeType,
              data: rawData
            }
          });
          addLog('tool', `📎 Prepared ${file.name} (${file.mimeType})`, { 
            sizeKB: `${Math.round(rawData.length / 1024)} KB` 
          });
        });

        // Add text prompt AFTER files (so AI analyzes files in context of the prompt)
        const finalPrompt = text && text.trim() 
          ? text 
          : `I've attached ${attachments.length} file(s) (${fileNames}). Please analyze them carefully and tell me what you find. Be specific and accurate.`;
        
        parts.push({
          text: finalPrompt
        });

        // Send as a SINGLE turn with all parts together
        sessionRef.current.sendClientContent({
          turns: [{
            role: 'user',
            parts
          }],
          turnComplete: true
        });

        // UI Update
        const displayText = text || `[Attached ${attachments.length} files: ${fileNames}]`;
        setMessages(prev => {
          const appended = [...prev, {
          id: `${Date.now()}-u`,
          role: 'user' as const,
          text: displayText,
          timestamp: Date.now()
        }];

          return appended.length > maxContextMessages
            ? appended.slice(-maxContextMessages)
            : appended;
        });

        addLog('success', `✓ Multimodal message sent: ${attachments.length} files + prompt`);
      } catch (err: any) {
        console.error('Multimodal transmission failed:', err);
        addLog('error', `Transmission Error: ${err.message}`);
      }
    } else {
      addLog('warning', 'Connection unavailable. Establish session before sending files.');
    }
  }, [status, addLog, maxContextMessages]);

  // Track which files have already been pushed to the context to avoid duplicates
  const prevAttachedFilesRef = useRef<Set<string>>(new Set());

  // AUTO-UPLOAD ATTACHMENTS: 
  // Watch for new files and push them to the model context immediately.
  // This solves the issue where "Add File" items were not visible to the Vision model.
  useEffect(() => {
    // If not connected, just reset the tracker so we send them when we do connect
    if (status !== ConnectionStatus.CONNECTED) {
      prevAttachedFilesRef.current.clear();
      return;
    }

    // Identify files that haven't been sent to the AI yet
    const newFiles = attachedFiles.filter(f => !prevAttachedFilesRef.current.has(f.name));

    if (newFiles.length > 0 && sessionRef.current) {
      addLog('info', `🔄 Auto-syncing ${newFiles.length} new attachments to AI context...`);

      const parts: any[] = [];

      newFiles.forEach(file => {
        // Extract raw base64 (remove data:image/png;base64, prefix if present)
        const rawData = file.data.includes(',') ? file.data.split(',')[1] : file.data;
        
        parts.push({
          inlineData: {
            mimeType: file.mimeType,
            data: rawData
          }
        });
        
        // Mark as sent
        prevAttachedFilesRef.current.add(file.name);
      });

      // Add a system note so the AI knows these are context files, not necessarily a prompt to answer immediately
      parts.push({
        text: `[SYSTEM_DATA_LOAD] User has attached these ${newFiles.length} file(s) for context. Analyze them silently. Wait for user's voice command or question about them.`
      });

      try {
        sessionRef.current.sendClientContent({
          turns: [{
            role: 'user',
            parts
          }],
          turnComplete: true
        });
        addLog('success', `✓ ${newFiles.length} Files uploaded to AI Vision Context`);
      } catch (err: any) {
        console.error('Auto-upload failed:', err);
      }
    }
    
    // Cleanup: If a file was removed from the UI, remove it from our "sent" set
    // so if it's added again, we re-send it.
    const currentFileNames = new Set(attachedFiles.map(f => f.name));
    prevAttachedFilesRef.current.forEach(name => {
      if (!currentFileNames.has(name)) {
        prevAttachedFilesRef.current.delete(name);
      }
    });

  }, [attachedFiles, status, addLog]);

  return {
    connect,
    disconnect: cleanup,
    status,
    messages,
    currentInput,
    currentOutput,
    error,
    analyser: outputAnalyserRef.current,
    micAnalyser: inputAnalyserRef.current,
    sendVideoFrame,
    sendTextMessage,
    sendMultimodalMessage,
    currentThought,
    isThinking,
    thinkingEnabled,
    setThinkingEnabled,
    addLog,
    logs
  };
};

import { useEffect, useState, useRef } from 'react';

const electronAPI = (window as any).electronAPI;

export const useZoom = () => {
  const [zoomLevel, setZoomLevel] = useState(1);
  const isInitialApplied = useRef(false);

  const calculateOptimalZoom = () => {
    // 2000px target width (Safe for all sidebars + hub)
    const targetWidth = 2000;
    
    // Asli Hardware Width use karenge (ye kabhi nahi badalti, isliye stability 100% hogi)
    const hardwareWidth = window.screen.width;
    
    const ratio = hardwareWidth / targetWidth;
    
    // Limits: Laptop screens ke liye ~0.65-0.75, Desktop ke liye 1.0
    return Math.min(Math.max(ratio, 0.6), 1.2);
  };

  useEffect(() => {
    if (!electronAPI) return;

    const applyScaling = () => {
      const optimal = calculateOptimalZoom();
      electronAPI.setZoomFactor(optimal);
      setZoomLevel(optimal);
      isInitialApplied.current = true;
      console.log(`Final Auto-Scale Applied: ${Math.round(optimal * 100)}% based on screen width ${window.screen.width}px`);
    };

    // Immediately apply scaling to avoid visual jumps
    applyScaling();

    // Listen for resize events to re-apply if needed (optional, mostly for dev)
    /* window.addEventListener('resize', applyScaling); */

    // Manual Shortcuts remains stable
    const handleKeyDown = (e: KeyboardEvent) => {
      const isControl = e.ctrlKey || e.metaKey;
      if (isControl) {
        if (e.key === '=' || e.key === '+') {
          e.preventDefault();
          const current = (window as any).electronAPI.getZoomFactor();
          (window as any).electronAPI.setZoomFactor(Math.min(current + 0.1, 2.5));
        } else if (e.key === '-' || e.key === '_') {
          e.preventDefault();
          const current = (window as any).electronAPI.getZoomFactor();
          (window as any).electronAPI.setZoomFactor(Math.max(current - 0.1, 0.4));
        } else if (e.key === '0') {
          e.preventDefault();
          applyScaling();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      // clearTimeout(timer); // Timer removed
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  return { zoomLevel };
};

/**
 * Audio Player for Gemini Live API
 * Handles seamless 24kHz PCM audio playback with timestamp-based scheduling
 * to avoid gaps and clicks between chunks
 */

export class AudioPlayer {
  private context: AudioContext;
  private nextStartTime: number = 0;
  private activeSources: AudioBufferSourceNode[] = [];

  constructor() {
    // Create AudioContext for playback (will handle 24kHz upsampling to system rate)
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)({
      sampleRate: 48000, // System default, will upsample 24kHz internally
    });
  }

  /**
   * Convert Base64 PCM data to Int16Array
   */
  private base64ToInt16(base64: string): Int16Array {
    const binaryString = window.atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    
    // Create Int16Array from bytes (Little-Endian)
    const int16Array = new Int16Array(bytes.buffer);
    return int16Array;
  }

  /**
   * Convert Int16 PCM to Float32 for Web Audio API
   */
  private int16ToFloat32(int16Data: Int16Array): Float32Array {
    const float32 = new Float32Array(int16Data.length);
    
    for (let i = 0; i < int16Data.length; i++) {
      // Normalize to [-1.0, 1.0]
      float32[i] = int16Data[i] / 32768.0;
    }
    
    return float32;
  }

  /**
   * Schedule an audio chunk for playback
   * Uses precise timing to ensure seamless playback
   */
  scheduleChunk(base64Audio: string): void {
    try {
      // Resume context if suspended
      if (this.context.state === 'suspended') {
        this.context.resume();
      }

      // Decode Base64 → Int16 → Float32
      const pcm16 = this.base64ToInt16(base64Audio);
      const float32Data = this.int16ToFloat32(pcm16);

      if (float32Data.length === 0) return;

      // Create AudioBuffer with 24kHz sample rate (Gemini output rate)
      const buffer = this.context.createBuffer(1, float32Data.length, 24000);
      buffer.getChannelData(0).set(float32Data);

      // Create source node
      const source = this.context.createBufferSource();
      source.buffer = buffer;
      source.connect(this.context.destination);

      // Calculate start time
      const now = this.context.currentTime;
      
      // If we're behind (buffer underrun), reset with small safety margin
      if (this.nextStartTime < now) {
        this.nextStartTime = now + 0.05; // 50ms buffer
      }

      // Schedule playback
      source.start(this.nextStartTime);
      
      // Track active source
      this.activeSources.push(source);
      
      // Cleanup when finished
      source.onended = () => {
        const index = this.activeSources.indexOf(source);
        if (index > -1) {
          this.activeSources.splice(index, 1);
        }
      };

      // Update next start time
      this.nextStartTime += buffer.duration;

    } catch (error) {
      console.error('Error scheduling audio chunk:', error);
    }
  }

  /**
   * Clear playback queue (for interruptions/barge-in)
   */
  clear(): void {
    // Stop all active sources
    this.activeSources.forEach(source => {
      try {
        source.stop();
        source.disconnect();
      } catch (e) {
        // Source might already be stopped
      }
    });
    
    this.activeSources = [];
    this.nextStartTime = 0;
    
    console.log('AudioPlayer: Playback queue cleared');
  }

  /**
   * Get play state
   */
  isPlaying(): boolean {
    return this.activeSources.length > 0;
  }

  /**
   * Cleanup resources
   */
  dispose(): void {
    this.clear();
    this.context.close();
  }
}

/**
 * Modern Audio processing utilities for Gemini Live API
 * Uses AudioWorkletNode instead of deprecated ScriptProcessorNode
 */

export const PCM_SAMPLE_RATE = 16000;

export class AudioProcessor {
  private context: AudioContext;
  private inputSource: MediaStreamAudioSourceNode | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private stream: MediaStream | null = null;
  
  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)({
      sampleRate: PCM_SAMPLE_RATE,
    });
  }

  async startRecording(onData: (base64Data: string) => void) {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }

    try {
      // Load AudioWorklet processor
      await this.context.audioWorklet.addModule('/audio-processor-worklet.js');
    } catch (err) {
      console.warn('AudioWorklet not supported, this should not happen in modern browsers', err);
      throw new Error('AudioWorklet not supported');
    }

    // Get microphone stream
    this.stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        channelCount: 1,
        sampleRate: PCM_SAMPLE_RATE,
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      }
    });

    this.inputSource = this.context.createMediaStreamSource(this.stream);
    
    // Create AudioWorklet node
    this.workletNode = new AudioWorkletNode(this.context, 'audio-capture-processor');
    
    // Listen for audio data from worklet
    this.workletNode.port.onmessage = (event) => {
      if (event.data.type === 'audio-data') {
        const base64 = this.arrayBufferToBase64(event.data.data);
        onData(base64);
      }
    };

    // Connect: Mic -> Worklet (no need to connect to destination)
    this.inputSource.connect(this.workletNode);
  }

  stopRecording() {
    if (this.workletNode && this.inputSource) {
      this.inputSource.disconnect();
      this.workletNode.disconnect();
      this.workletNode.port.onmessage = null;
    }
    
    if (this.stream) {
      this.stream.getTracks().forEach(track => track.stop());
    }
    
    this.inputSource = null;
    this.workletNode = null;
    this.stream = null;
  }

  private arrayBufferToBase64(buffer: ArrayBuffer): string {
    let binary = '';
    const bytes = new Uint8Array(buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
  }
}

