export const generateLinkedInDrafts = async (
  apiKey: string,
  profile: any,
  stories: NewsStory[]
): Promise<LinkedInDraft[]> => {
  logDashboardAi('generateLinkedInDrafts:start', {
    profession: String(profile?.profession || ''),
    storiesCount: Array.isArray(stories) ? stories.length : 0,
  });

  const topStoryContext = stories
    .slice(0, 5)
    .map((story) => `- ${story.headline} (${story.source})`)
    .join('\n');

  const prompt = `
Generate exactly ${LINKEDIN_MIN_DAILY_DRAFTS} LinkedIn post drafts for today.

User context:
- Profession: ${profile?.profession || 'Not provided'}
- Bio: ${profile?.bio || 'Not provided'}
- Location: ${profile?.location || 'Not provided'}
- LinkedIn headline/about (if available): ${profile?.linkedinHeadline || profile?.linkedinAbout || 'Not provided'}

Top stories for grounding:
${topStoryContext || '- No stories available'}

Constraints:
- Topic priority: AI, Tech, product, startups, automation, leadership.
- Rotate styles: insight, question, opinion, how-to, trend commentary, personal lesson.
- Keep each draft 500-1000 characters.
- Include 4-6 relevant hashtags.
- Match a professional but human tone based on the user context.

Return ONLY valid JSON:
{
  "drafts": [
    {
      "text": "string",
      "hashtags": ["#tag"],
      "engagementType": "educational|opinion|story"
    }
  ]
}
`;

  let parsed: any;
  try {
    parsed = await modelJsonRequest(apiKey, prompt, {
      preferSearch: false,
      operation: 'linkedin_drafts',
    });
  } catch (error: any) {
    logDashboardAi('generateLinkedInDrafts:modelFailedUsingFallback', {
      error: error?.message || 'Unknown error',
    });
    return buildFallbackLinkedInDrafts(profile, stories);
  }
  const drafts = Array.isArray(parsed?.drafts) ? parsed.drafts : [];

  logDashboardAi('generateLinkedInDrafts:parsed', { draftsCount: drafts.length });

  const normalizedDrafts = drafts.slice(0, LINKEDIN_MIN_DAILY_DRAFTS).map((draft: any, idx: number) => {
    const text = String(draft?.text || '');
    return {
      id: toId('linkedin', idx),
      text,
      hashtags: Array.isArray(draft?.hashtags)
        ? draft.hashtags.map(String)
        : [],
      engagementType: ['educational', 'opinion', 'story'].includes(draft?.engagementType)
        ? draft.engagementType
        : 'educational',
      charCount: text.length,
      approved: false,
    } as LinkedInDraft;
  });

  let completedDrafts = normalizedDrafts;
  if (completedDrafts.length < LINKEDIN_MIN_DAILY_DRAFTS) {
    const fallbackDrafts = buildFallbackLinkedInDrafts(profile, stories);
    const needed = LINKEDIN_MIN_DAILY_DRAFTS - completedDrafts.length;
    completedDrafts = [...completedDrafts, ...fallbackDrafts.slice(0, needed)].slice(
      0,
      LINKEDIN_MIN_DAILY_DRAFTS
    );
    logDashboardAi('generateLinkedInDrafts:topupWithFallback', {
      modelDrafts: normalizedDrafts.length,
      needed,
      finalCount: completedDrafts.length,
    });
  }

  logDashboardAi('generateLinkedInDrafts:completed', {
    returnedDrafts: completedDrafts.length,
  });

  return completedDrafts;
};

export const generateArticleTldr = async (apiKey: string, articleText: string): Promise<string> => {
  const ai = getAi(apiKey);
  const prompt = `Summarize this article in 3 concise bullet points:\n\n${articleText.slice(0, 12000)}`;

  logDashboardAi('generateArticleTldr:start', {
    articleLength: articleText.length,
    promptLength: prompt.length,
  });

  for (const model of DASHBOARD_MODEL_CANDIDATES) {
    try {
      logDashboardAi('generateArticleTldr:attempt', { model });
      const result = await (ai as any).models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
      });

      const text = String(result?.response?.text?.() || '').trim();
      if (text) {
        logDashboardAi('generateArticleTldr:success', { model, tldrLength: text.length });
        return text;
      }
    } catch {
      logDashboardAi('generateArticleTldr:attemptFailed', { model });
    }
  }

  logDashboardAi('generateArticleTldr:fallbackUsed');
  return 'TL;DR unavailable right now due to model response issues.';
};

import { GoogleGenAI } from "@google/genai";

export interface DashboardData {
  headlines: string[];
  weather: {
    today: string;
    tomorrow: string;
    dayAfter: string;
  };
  lastUpdated: number;
}

/**
 * Fetches latest news headlines and weather data using Gemini 2.5 Flash's web search.
 */
export const fetchDashboardData = async (
  apiKey: string,
  location: string,
  interests: string[]
): Promise<DashboardData | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey });
    
    // Using gemini-2.0-flash-exp as it's the latest and supports search natively
    const prompt = `
      You are a specialized dashboard assistant for "Theta AI". 
      User Location: ${location || 'Pakistan (General)'}
      User Interests: ${interests.join(', ')}

      TASK:
      1. Search for the top 5 latest news headlines relevant to the user's location and interests. 
      2. Provide the weather forecast for today, tomorrow, and the day after for the user's location.
      3. CRITICAL: Provide the headlines in Roman Urdu (Urdu written in English alphabets) to match the app's aesthetic.
      4. Weather should be concise with an appropriate emoji.

      FORMAT: Respond ONLY with a valid JSON object:
      {
        "headlines": ["Headline 1", "Headline 2", ...],
        "weather": {
          "today": "Aaj: 22°C ☀️",
          "tomorrow": "Kal: 21°C 🌦️",
          "dayAfter": "Parson: 22°C 🌤️"
        }
      }
    `;

    const result = await (ai as any).models.generateContent({
      model: "gemini-2.0-flash-exp",
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      tools: [{ googleSearch: {} } as any]
    });

    const response = result.response;
    const text = response.text();
    
    // Extract JSON from response
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const data = JSON.parse(jsonMatch[0]);
      return {
        ...data,
        lastUpdated: Date.now()
      };
    }

    return null;
  } catch (error: any) {
    console.error("Dashboard Fetch Error:", error);
    return null;
  }
};

import { generateImage } from './genai';
import { type SystemLog } from '../types/gemini-live';

export interface ToolExecutionContext {
  addLog: (type: SystemLog['type'], message: string, details?: any) => void;
  onVisualizingChanged?: (isVisualizing: boolean) => void;
  onImageGenerated?: (imageUrl: string) => void;
  onDiagramGenerated?: (code: string) => void;
  onMemoriesUpdated?: (memories: any[]) => void;
  onContactsUpdated?: (contacts: any[]) => void;
  onDashboardUpdated?: (data: { headlines: string[], weather: any }) => void;
  onNotesUpdated?: (notes: any[]) => void;
  onTasksUpdated?: (tasks: any[]) => void;
  electronAPI: any;
  apiKey: string;
  onYouTubePlay?: (videoId: string) => void;
  getAttachedFiles?: () => any[];
  cleanup: () => void;
}

const logToolRunner = (stage: string, details?: Record<string, unknown>) => {
  const timestamp = new Date().toISOString();
  if (details) {
    console.debug(`[GeminiToolRunner ${timestamp}] ${stage}`, details);
    return;
  }
  console.debug(`[GeminiToolRunner ${timestamp}] ${stage}`);
};

export const handleToolCalls = async (
  toolCalls: any[], 
  session: any, 
  context: ToolExecutionContext
) => {
  const { 
    addLog, 
    onVisualizingChanged, 
    onImageGenerated, 
    onDiagramGenerated, 
    onMemoriesUpdated, 
    onContactsUpdated,
    onDashboardUpdated,
    onNotesUpdated,
    onTasksUpdated,
    electronAPI,  
    apiKey, 
    onYouTubePlay,
    cleanup 
  } = context;

  const uiAccessModeByTool: Record<string, 'read' | 'write' | 'update' | 'delete'> = {
    generate_image: 'update',
    render_diagram: 'update',
    store_memory: 'write',
    get_memories: 'read',
    update_dashboard: 'update',
    add_note: 'write',
    read_notes: 'read',
    add_task: 'write',
    read_tasks: 'read',
    add_contact: 'write',
    read_contacts: 'read',
    play_youtube_video: 'update',
    read_attached_files: 'read',
    semantic_workspace_search: 'read',
  };

  const buildUiAccessDetail = (toolName: string, args: any) => {
    switch (toolName) {
      case 'generate_image':
        return `Render generated image in Visual Hub: ${String(args?.prompt || '').slice(0, 120)}`;
      case 'render_diagram':
        return `Render ${args?.type || 'diagram'} in Visual Hub`;
      case 'store_memory':
        return `Write memory entry: ${String(args?.content || '').slice(0, 120)}`;
      case 'get_memories':
        return 'Read stored memories from Memory module';
      case 'update_dashboard':
        return 'Update dashboard cards (headlines/weather)';
      case 'add_note':
        return `Create note: ${String(args?.title || 'Untitled').slice(0, 80)}`;
      case 'read_notes':
        return `Read notes${args?.query ? ` (query: ${String(args.query).slice(0, 80)})` : ''}`;
      case 'add_task':
        return `Create task: ${String(args?.text || '').slice(0, 100)}`;
      case 'read_tasks':
        return `Read task list${args?.filter ? ` (filter: ${args.filter})` : ''}`;
      case 'add_contact':
        return `Create/update contact: ${String(args?.name || '').slice(0, 80)}`;
      case 'read_contacts':
        return `Read contacts${args?.query ? ` (query: ${String(args.query).slice(0, 80)})` : ''}`;
      case 'play_youtube_video':
        return `Open video player panel for query: ${String(args?.query || '').slice(0, 120)}`;
      case 'read_attached_files':
        return 'Read attached files currently shown in UI context';
      case 'semantic_workspace_search':
        return `Run semantic workspace search: ${String(args?.query || '').slice(0, 120)}`;
      default:
        return `UI ${uiAccessModeByTool[toolName] || 'update'} access requested via ${toolName}`;
    }
  };

  for (const call of toolCalls) {
    const args = (call.args || {}) as any;
    const startedAt = Date.now();

    logToolRunner('toolCall:start', {
      name: call.name,
      id: call.id,
      argKeys: Object.keys(args || {}),
    });

    if (uiAccessModeByTool[call.name]) {
      if (typeof electronAPI?.requestActionApproval !== 'function') {
        logToolRunner('toolCall:blockedApprovalBridgeMissing', {
          name: call.name,
          id: call.id,
        });
        session.sendToolResponse({
          functionResponses: [{
            name: call.name,
            id: call.id,
            response: { error: 'UI access approval bridge is unavailable. Action blocked.' }
          }]
        });
        continue;
      }

      const accessMode = uiAccessModeByTool[call.name];
      const detail = buildUiAccessDetail(call.name, args);
      logToolRunner('toolCall:approvalRequested', {
        name: call.name,
        id: call.id,
        accessMode,
      });
      const approval = await electronAPI.requestActionApproval({
        action: `Theta UI ${accessMode.toUpperCase()} Access`,
        detail,
        source: `gemini-tool-runner:${call.name}`,
        rawPayload: {
          tool: call.name,
          accessMode,
          args,
        },
      });

      logToolRunner('toolCall:approvalResolved', {
        name: call.name,
        id: call.id,
        approved: approval?.approved === true,
      });

      if (!approval?.approved) {
        addLog('warning', `UI access denied for ${call.name}`);
        logToolRunner('toolCall:blockedByUser', {
          name: call.name,
          id: call.id,
        });
        session.sendToolResponse({
          functionResponses: [{
            name: call.name,
            id: call.id,
            response: { error: 'Permission denied by user. UI action was not executed.' }
          }]
        });
        continue;
      }
    }

    if (call.name === 'generate_image') {
      const { prompt } = call.args as any;
      addLog('tool', `Invoking Image Generation`, { prompt });

      onVisualizingChanged?.(true);
      try {
        const imageUrl = await generateImage(prompt, apiKey);
        if (imageUrl) {
          addLog('success', 'Image generated successfully');
          onImageGenerated?.(imageUrl);

          onVisualizingChanged?.(false);
          await electronAPI.saveImage({ 
            base64Data: imageUrl, 
            mimeType: 'image/png' 
          });

          session.sendToolResponse({
            functionResponses: [{
              name: 'generate_image',
              id: call.id,
              response: { result: 'Image generated and auto-saved to Downloads folder.' }
            }]
          });
        } else {
          onVisualizingChanged?.(false);
          session.sendToolResponse({
            functionResponses: [{
              name: 'generate_image',
              id: call.id,
              response: { error: 'Image model returned no image data. Please try a different prompt.' }
            }]
          });
        }
      } catch (err: any) {
        console.error('Image generation/save failed:', err);
        onVisualizingChanged?.(false);
        session.sendToolResponse({
          functionResponses: [{
            name: 'generate_image',
            id: call.id,
            response: { error: err?.message || 'Image generation failed.' }
          }]
        });
      }
    } else if (call.name === 'render_diagram') {
      const { code, type } = call.args as any;
      addLog('tool', `Rendering ${type} Diagram`, { codeLength: code.length });
      onVisualizingChanged?.(true);

      onDiagramGenerated?.(code);
      onVisualizingChanged?.(false);
      
      session.sendToolResponse({
        functionResponses: [{
          name: 'render_diagram',
          id: call.id,
          response: { result: 'Diagram rendered successfully in the Visual Intelligence Hub.' }
        }]
      });
    } else if (call.name === 'store_memory') {
      const { content, category } = call.args as any;
      addLog('tool', 'Storing information to memory', { category });

      const newMemory = {
        id: Date.now().toString(),
        content,
        category: category || 'personal',
        timestamp: Date.now()
      };

      // Load existing, add new, and save
